/* 2015年6月29日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h27-20150629-9","dateIso":"2015-06-29","title":"2015年6月29日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4856#one","fetchedAt":"2026-08-14","characters":63586,"voices":[{"i":1,"speaker":"塚本委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査および報告事項等を予定しております。\n本日も効率的な委員会運営にご協力よろしくお願いいたします。\n────────────────────────────────────────────\n１ 議案審査\n(1) 第５８号議案 品川区女性福祉資金貸付条例の一部を改正する条例"},{"i":2,"speaker":"塚本委員長","text":"それでは、予定表１、議案審査を行います。\n初めに、(1)第５８号議案、品川区女性福祉資金貸付条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":3,"speaker":"廣田子ども家庭支援課長","text":"それでは、私から第５８号議案、品川区女性福祉資金貸付条例の一部を改正する条例についてご説明申し上げます。\nお手元にＡ４、１枚の資料をご用意してございます。本案の資料の改正理由にお示ししましたように、東京都女性福祉資金の償還に係る延滞利子の割合が見直されたため、昭和５０年に都から区へ移管された事業という背景がございます関係から、均衡を考慮しまして、区の女性福祉資金の償還に係る延滞利子を見直すというものでございます。\n内容につきましては、お手元の資料の新旧対照表にお示しいたしましたとおり、借受人が償還期日までに元利金を支払わなかったときに徴す延滞利子の割合を年１０.７５％から年５％に改正するというものでございます。\n施行期日につきましては、公布の日といたしまして、平成２７年４月１日以後の期間に係る延滞利子の計算につきまして、改正後の延滞利子を適用するというものでございます。"},{"i":4,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":5,"speaker":"石田（ち）委員","text":"１０.７５％から５％という、なぜ５％なのか伺いたいのと、あと、事務事業概要のほうで、貸付状況を見ますと、そんなに、５件とか、８件とか、６件という話で、あまり多くないとは思うのですけれども、ここの中で返せていない、延滞している方というのは、いるのかどうかお伺いしたいと思います。"},{"i":6,"speaker":"廣田子ども家庭支援課長","text":"５％につきましては、東京都の女性福祉資金の前段といいますか、もともと母子・父子福祉資金というものがございまして、ひとり親に対する貸付の資金がございます。女性福祉資金は、それとあわせまして、相談等で貸付を行うようなものでございまして、平成２７年４月１日から母子・父子福祉資金のほうも改正になりまして５％というふうになっております。民法の金銭の債務に関しましての延滞利子が５％ということになっておりまして、区の私債権の管理条例におきましても、延滞利子は５％ということで、東京都の女性福祉資金５％にも合わせるところもございますが、区の私債権管理の延滞利子も５％ということでありますので、５％ということで提案しております。\n延滞の人数につきましては、全体で３０数名程度でございます。"},{"i":7,"speaker":"石田（ち）委員","text":"そうすると、１年間で借りられている方は５名とか８名とか少ないけれども、延滞されている方は想像で３０数名いるということでいいのでしょうか。\nそれとあと、母子・父子の貸付の東京都のほうのものを利用されている方というのは、どれくらい含んでいるかはわかるかどうか。わかれば教えてください。"},{"i":8,"speaker":"廣田子ども家庭支援課長","text":"女性福祉資金は就学資金と準備金になっておりまして、就学資金で高校であれば３年間、貸し付けている間は返還はしませんので、過去に貸付をした方の中で、さらに督促をしても返還が滞っている方が現在３６名程度、今日時点のものではないのですが、少し前で３６名ということになっております。\n新規につきましては、少ないのですけれども、優先順位として母子・父子福祉資金の貸付のほうが先に該当する方はそちらをということになっておりますので、そちらに該当している方に関しましては、そちらで貸付をしているということなので人数は少なくなっております。平成２６年度で、母子福祉資金につきましては、種類が多くなっておりますので、就学資金につきましては平成２６年度９０件ということになっております。"},{"i":9,"speaker":"浅野委員","text":"この貸付の件ですけれども、１０.７５％の基準のものについては、あくまで１０.７５％の利息が継続をするということなのでしょうか。５％は、この期日以降については５％ということで、人によっては１０.７５％かかる方が結構いらっしゃるのかと思いながら聞いていたのですけれども、古い部分について、利息がたまって支払いきれないとか、返しきれないとか、そういうケースももしかしたらあるのかと思っているのですが、こちらのほうの実態を教えていただきたいと思います。"},{"i":10,"speaker":"廣田子ども家庭支援課長","text":"委員のおっしゃるとおりで、その期間前については１０.７５％を適用する予定でございます。現在、滞納している方が３０数名いらっしゃるのですけれども、債権管理のほうが順調に督促はしたり、電話とかはしているのですけれども、実際問題として、分納してほしいとかという交渉については、まだ積極的にはやっておりませんで、払えない方に関しても放棄に匹敵するかどうかということも含めまして、きちんと精査しなければいけないということで、平成２７年度から弁護士に委任する予算をとっておりますので、これから弁護士に委任しまして実態を、滞納されている方と交渉をしていって、払わないのか、払えないのかというところを精査して動いていく予定でございます。"},{"i":11,"speaker":"浅野委員","text":"大変な生活の状況の中で借りられた方も当然おられるかと思うので、やはりそこら辺は、滞納されている方については一人一人やはり丁寧に状況を伺いながら、適切な措置をとっていただければと、そのように思いますので、よろしくお願いします。"},{"i":12,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、初めに、自民党・子ども未来からお願いいたします。"},{"i":13,"speaker":"鈴木（博）委員","text":"賛成か反対かでいいですか。"},{"i":14,"speaker":"塚本委員長","text":"そうですね。"},{"i":15,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":16,"speaker":"浅野委員","text":"賛成です。"},{"i":17,"speaker":"石田（ち）委員","text":"賛成です。"},{"i":18,"speaker":"大倉委員","text":"賛成です。"},{"i":19,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":20,"speaker":"塚本委員長","text":"それでは、これより、第５８号議案、品川区女性福祉資金貸付条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本件は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":21,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決いたしました。\n────────────────────────────────────────────\n(2) 第５９号議案 品川区立就学前乳幼児教育施設条例の一部を改正する条例"},{"i":22,"speaker":"塚本委員長","text":"次に、(2)第５９号議案、品川区立就学前乳幼児教育施設条例の一部を改正する条例について議題に供します。\nそれでは、本件について、理事者より説明願います。"},{"i":23,"speaker":"竹田保育課長","text":"私からは、第５９号議案、品川区立就学前乳幼児教育施設条例の一部改正についてご説明いたします。\n１、改正理由ですが、本年４月から子ども・子育て支援新制度が施行されたことに伴い、区立幼稚園保育料について所得に応じた応能負担に変更する改正案を提案しているところでございます。\n就学前乳幼児教育施設であるぷりすくーる西五反田においても、新制度の趣旨を鑑み、これまで一律であった幼児教育施設（３歳～５歳）の保育料について国基準額および区立幼稚園保育料を考慮して、応能負担とするため全面的に改定する必要があると考え、ご審議いただくものでございます。\n２、改正案ですが、1)現行、月額保育料は、一律２万３,０００円ですが、国基準額、区立幼稚園保育料（案）および現行の私立幼稚園の園児保護者補助金の枠組みから、所得階層をお手元の資料のとおり８区分とするものでございます。\nぷりすくーる西五反田に通う園児の保護者に対しましては補助金が支給されておりまして、今までの現行の保護者の方の実負担額は、保育料を記載しました１つ右の行のとおりでございます。補助金をあわせて考えますと、実質的に応能負担となっておりました。\n今回の保育料改正案でございますが、今までの実負担額と比較しますと、第１階層の生活保護世帯および第２階層の区民税非課税世帯については引き続き０円、第３階層は、国基準額での第２階層と同額の３,０００円、第４階層から第８階層までは、実負担額の約１０％増となっております。ただし、第５階層においては第４階層と第６階層の保育料の差をなだらかなものとするため新設したものでございます。第８階層につきましては、国基準額の上限額と同額の２万５,７００円といたしました。\nなお、入園料は現行のとおり１万円といたします。\nまた、あわせて新制度に基づく保育の短時間認定を受けた者に係る時間外保育を実施するための諸規定の改正を行うものでございます。\n３、新旧対照表は、別紙「新旧対照表」のとおりでございます。\n４、経過措置ですが、保育料の改定にあたり、経過措置として、平成２７年度在園児については、従来の額と同額といたします。\n５、施行日は、月額保育料に関する部分は平成２８年４月１日、その他の諸規定の改正は公布の日から施行いたします。"},{"i":24,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等ございましたら、ご発言願います。"},{"i":25,"speaker":"石田（ち）委員","text":"この新旧対照表のところで、第３条の、新のほうでは「時間外保育」、旧のほうでは「延長夜間保育」、この違いは何か、どう違ってくるのかを教えていただきたいのと、あと、第７条の「保育時間内延長保育」というのはどういうことなのか、基本的なところを教えていただきたいと思います。"},{"i":26,"speaker":"竹田保育課長","text":"延長時間に関しては、従来は開所時間外の延長夜間保育料の規定のみでございましたが、新制度にございまして、短時間認定を受けたものが１日の最大の利用時間が８時間となったことから、開所時間内においても８時間を超える利用が想定されるため、その利用料として１人１時間当たり４００円を徴収するという規定を今回設けたものでございます。\n第３条の違いですけれども、従来は延長夜間保育ということで、６時半以降の延長のみを規定しておりましたが、先ほど申し上げましたとおり、短時間利用の方の認定に伴いまして、開所時間内も時間外保育料を徴収する必要があるため、「時間外保育」という言葉を使いまして、その中に延長夜間保育と保育時間内延長保育という２つの形態を設けたものでございます。"},{"i":27,"speaker":"石田（ち）委員","text":"わかりました。\nそれとあと、階層が第１から第８までつくられたというところで、第３階層から第８階層までの所得割で出ているのですけれども、ちょっとわかりづらいので、この方々の年間所得は大体どれぐらいになるのかということを教えてください。\nそれから、この階層別の人数、割合を教えていただきたいと思います。\nそれとあと、階層の基本的な考え方というのは、第１から第８までにした考え方をお聞かせください。"},{"i":28,"speaker":"竹田保育課長","text":"まず、各階層の年収でございますが、夫婦２人と子ども２人のモデルケースでございます。第１階層は生活保護ですので、第２階層は年収２７０万円、第３階層は年収３６０万円、第４階層は年収６８０万円、第６階層は年収７３０万円、第７階層が年収１,００６万円、第８階層が年収１,００６万円を超えるものでございます。\nそれから、所得階層の割合でございますが、第１階層が０％、第２階層が１.４％、第３階層が２.８％、第４階層が２５.４％、それから第５、第６階層は合わせて４.２％、第７階層が１１.８％、第８階層は２２.５％で、これ以外に区民以外の方、あるいは補助金未申請のため所得を把握していない方が３２.４％ございます。\nそれから、料金改定にあたっての基本的な考え方でございますが、第１階層、第２階層は０円としている、あるいは第３階層は国基準額の第２階層と同額の３,０００円としている等、低所得者の方には十分配慮した内容となっております。第３階層は国基準の第２階層と同額ということで、十分、低所得者に配慮したものでございます。"},{"i":29,"speaker":"浅野委員","text":"新旧対照表の第６条なのですけれども、旧のほうですと、「保育時間外に特に保育する必要があると認められる乳幼児に対し、延長夜間保育を実施する」とあって、今度新しいほうは、「１日当たり１１時間までに限る」というような数字が出ていて、あと、「保育園の保育時間外に特に保育する必要があると認められる乳幼児に対し、延長夜間保育を実施する」というふうにあるのですけれども、ここの大きな違いがよく、数字が出てきたのかなというのは見られるところなのですが、この場合、旧で利用していた方が、例えば１月当たり平均２７５時間を超えるようなケースというのは過去にあったのか、それとも全くなかったのか、この２７５時間は何らかの形で決められた数字だと思うのですけれども、どのようなレベルで決められたのか教えてください。"},{"i":30,"speaker":"竹田保育課長","text":"第６条に関する部分でございますが、従来は開所時間である６時半以降を利用する方について、時間外延長夜間保育料ということで徴収しておりました。１１時間を２５日利用した場合は、この２７５時間という時間になりまして、各１日当たり１１時間を超える利用分については、延長夜間保育料として徴収するという改正でございます。"},{"i":31,"speaker":"浅野委員","text":"数字的にはわかるのですけれども、実際に今まで使われていた方に、簡単に言いますと影響があるのかどうか、今までここまでやっていたけれども、今回きつくなったとか、いや、緩くなったから例えばもっとできるのかとか、そういうところをお伺いしたいなと、そのように思うので、こういう方はと質問したのです。\nそれとあともう１つなのですけれども、これは改定によりまして保育料の総額はどのくらい変化があるのか、ほとんど変わらないのか、そこら辺の見通しを教えてください。"},{"i":32,"speaker":"竹田保育課長","text":"従来利用の方が引き続き標準時間認定を受けた場合は、その方については利用にあたっての制約といいますか、変更はございません。それで、従来利用されていた方で短時間に認定された方については、８時間以上の部分が時間外保育の保育料の対象となるという違いがございます。\nそれから、利用の状況でございますが、済みません、ちょっと手元に資料がないのですが、若干ご利用いただいているという状況でございます。\nそれから、全体の歳入の状況でございますが、ぷりすくーる西五反田は、指定管理者によって運営されておりまして、現在はその指定管理者が一律２万３,０００円掛ける人数分の保育料を徴収しております。今回の改正により、２万３,０００円よりも高額となるのは第８階層のみであるため、指定管理者が保護者から受け取る歳入は年間約３２０万円ほど減収となると予想しております。ただし、区が保護者へ直接助成しておりました補助金約６５０万円は不要となる見込みでございます。指定管理者の減収分については、来年度予算の委託料の中で補填していきたいと考えております。"},{"i":33,"speaker":"飯沼委員","text":"まず、先ほど、８階層の所得を伺ったのですね。お答えが年収だったので、すみません、年収だと多いですよね。可処分のところの所得を伺ったので、もう一回ここを教えていただきたいと思います。年収だと多くなってしまうので、どのくらいの生活水準かとわかるのはやはり所得だと思うので、すみません、もう一回ここのところを教えてください。"},{"i":34,"speaker":"竹田保育課長","text":"申しわけございません。今、所得に関する資料は持ち合わせてございません。申しわけございません。"},{"i":35,"speaker":"飯沼委員","text":"ここすごく、実質の生活がどの程度かと把握するのに、年収ではだめなのですよね。いろいろ控除される部分を除いて、どのくらい実際に生活に使えるという所得を見てみないと、実生活がどのくらいの人にどのくらいの保育料の負担がかかるのかというのがわからないので、改めて後で教えていただけますでしょうか。そうでないとこの判断がなかなかつかないと思うので、その点はよろしくお願いします。\nあと、先ほどご説明の中で、保護者実負担額というのが補助を受けた後の実質の負担だということにおいては、新しい保育料は第１階層、第２階層は０円なのですが、第３階層から第８階層まで全て保育料の負担が上がるという捉え方でよろしいのでしょうか。そこが１点です。\nあともう１つ、ぷりすくーるは預かり保育料がかかりますよね。預かり保育料のところと、あと、多分、幼稚園、就学前の施設なので、諸経費がかかると思うのですが、その辺がどの程度かかっているのか、トータルで見たとき、負担がどうなのかというところを教えていただきたいのですが、いかがでしょうか。"},{"i":36,"speaker":"竹田保育課長","text":"今お手元の保護者実負担額というのが現行でございます。現行と比較いたしますと、一部を除いて約１０％増の保育料の改定を想定しているものでございます。これは私立幼稚園との比較においては、約８割程度ということで、私立よりも低く設定しているものでございます。\nそれから、今回、預かり保育料あるいは諸経費等の値上げは今現在は考えていないところでございます。諸経費についての正確な金額は、すみません、今、持ち合わせていないところでございます。"},{"i":37,"speaker":"飯沼委員","text":"預かり保育は幾らなのですか。延長保育のところは０歳から２歳の保育園の部分なのですけれども、３歳から５歳のところは、多分、保育園で入っているお子さんが多数なので、幼稚園的な部分の時間よりも朝も夕方もかかる預かり保育を利用されている方が多いので、保育料のところだけで見るのではなく、プラスで預かり保育、何日利用するかによっても違いますけれども、１日単位の金額であると思っていますけれども、ここを加味して考えないと、私たちは父母の負担というのが理解できないので、どうなっているか教えてください。"},{"i":38,"speaker":"竹田保育課長","text":"預かり保育料につきましては、午前７時半から午後６時半までの利用が時間当たり８００円、それから、午前７時半から午後７時半までの時間帯の利用が９００円、それから午前７時半から午後８時半までの利用については時間１,０００円となっております。"},{"i":39,"speaker":"飯沼委員","text":"ありがとうございます。\n就学前幼児教育施設ということで、保育園とは違うわけですけれども、やはり保育園と幼稚園、また、ぷりすくーる、ここのところ、幼稚園もかなり預かりをやって就労の支援にもなっているというところにおいては、保育園と幼稚園とぷりすくーるの保育料の違い、どういう考え方でやっているのか。基本のところの、それぞれ応能負担に変えましたというところにおいて、違うわけですよね。同じ年齢で、例えば同じ保育時間にしても、施設によって違ってくるという、その辺の考え方、基本的に何かあったら聞かせてください。"},{"i":40,"speaker":"竹田保育課長","text":"施設の性格上、区立幼稚園、就学前ぷりすくーる、それから私立幼稚園という３つの形態があるのですけれども、区立幼稚園につきましては、私立幼稚園に比べて保育料を低く抑えたもの、それから、ぷりすくーるにつきましては、区立と私立の真ん中といいますか、私立幼稚園に準じた公設民営の施設という形で考えておりますので、私立幼稚園よりも少し抑えた保育料という設定の考え方でございます。"},{"i":41,"speaker":"金子子ども未来部長","text":"今、各施設の保育料の考え方というお尋ねでしたけれども、ぷりすくーるは、ご案内のとおり、今、設立して１１年目を迎えるところなのですけれども、設立した当初に、この施設の趣旨が私立幼稚園の蓄積した教育内容を生かした保育をしていただくというような形で、私立幼稚園を経営されている方々に参画していただいて運営をしている施設でございます。\nそのときに定めた保育料の考え方は、区内の私立幼稚園の平均額に近い数字にしようということで定めたものでございます。以来１０年、この保育料については改定してこなかったのですけれども、実際のところは私立幼稚園の平均的な保育料は若干上がってきていました。ですけれども、この間、日本の経済状況、社会経済状況がデフレ経済という形で進行していましたので、私どもとしては、私立の幼稚園にイコールという形ではなくて、この１０年間据え置いてきたというような経過であります。このたび、子ども・子育て支援新制度で、保育園、幼稚園全体として全て応能負担にしていこうというのが国の基本的な考え方でありますので、今回、改めて全体的な状況に鑑みて改定のお願いをしているところでございます。"},{"i":42,"speaker":"飯沼委員","text":"ありがとうございます。\n今回は国の応能負担の考え方を取り入れていくということなのですが、１つこれから保育需要が高まっていき、保育にかかわるお金全体の金額が増えていくと、今の国の考え方からすると、全体が増えていけば、保育料にはね返っていくという考えを持っているのですが、その点はいかがでしょうか。"},{"i":43,"speaker":"竹田保育課長","text":"今までの区立幼稚園、それからぷりすくーるにおきましては、一律の保育料の設定ということで行ってまいりましたが、国の新制度のスタートに伴いまして、国からはそれぞれの所得の能力に応じた応能負担という考え方が示されてきましたので、それに伴って改正するものでございますが、先ほどの所得の分布状況からも考えますと、歳入のほうは、今、全体的には少し上がっていくものというふうに考えております。"},{"i":44,"speaker":"伊藤副委員長","text":"何点か確認させてください。\n先ほど、３２０万円の減収という話を聞きましたけれども、これはつまり、国の方向性が変わったからこういうふうに変えていくと思うのだけれども、そうすると、いわゆる国の補助金であるとか、それから、ほかのところでこれが補填されるのでしょうかというのをお答えください。"},{"i":45,"speaker":"竹田保育課長","text":"通常の施設には国からの補助金が出るのですけれども、ぷりすくーるに関しましては、公設民営ということで補助金が出ませんので、今までは保護者に対する補助金は区のほかの施設との整合性を考えて、区で独自に補助金を出していたものでございます。"},{"i":46,"speaker":"伊藤副委員長","text":"そうすると、この減収は、つまり、品川区の一般財源から充当していくと思うのだけれども、先ほどの議論をずっと聞いていると、品川区民のバランスを考えていくと、税金を払っている方々というのは、子育て世代の方もいらっしゃるけれども、そうでない方も当然いらっしゃるし、それから、自分の子どもを保育園やこういう施設に預けていない方もいらっしゃる。そういういろいろバランスをずっと考えていくと、一般財源が投入されているからこそ、１億５,０００万円でしたか、それだけの予算を使ってこのぷりすくーるは運営されている。その一部を保育料としていただいていると思うのだけれども、それがこういう形で引き上げることについては、私は区民全体のバランス、特に一般財源を投入されていくことからすると、納税者の方々の意見を広く聞かないといけない。そうすると、この利害に関係している方々だけの意見でこれを判断するというよりは、もっと大きな観点、つまり、品川区の子育て全体の観点であるとか、それから品川区内にお住まいであるけれども、こういう施設に預けていない保護者の方々の意見を聞いた上で、総合的な保育システムを展開していかないと、税金の使い方についても、それから投入のしかたについても、さまざまな思いがあると思うのですけれども、改めて品川区のお考えをお聞かせください。"},{"i":47,"speaker":"竹田保育課長","text":"委員おっしゃるとおり、公設の施設については一般財源を投入して運営しているものですので、園に預けていらっしゃる方、あるいはそれ以外の方々、広くご意見を聴取してご理解いただくものとする必要があると考えております。\n今回は、開所以来１０年近く経過しておりますので、一定程度の料金改定をすることによって、区民の方のご理解を得られるものと考えましたので、今回、ご提案させていただいているものでございます。\n今後につきましても、経済状況あるいは区民の方のご意見を十分お聞きしながら、適正な保育料を考えていきたいと考えております。"},{"i":48,"speaker":"伊藤副委員長","text":"公的なサービスを提供するときには必ず税金が投入されているわけであって、それがあるからこそ見かけ上の保育料が少なく抑えられているわけです。これは誰でも理解すると思うのだけれども、そこのところをきちんとやっぱり多くの方々に、特に納税者の方々にご理解していただかないと、自分が納める区民税が特定の目的だけに使われていることについて、どれだけ理解をもらえるのか。やっぱりそれは品川区の権限でさまざまな政策を展開できるわけであるから、そのときにはやはり広く納税者の方々の意見を聞いた上で、その税の使われ方についても、こういう税金の投入の仕方、この事業自体に我々は反対するわけではないのだけれども、適正性があると思うのです。だから、今お話しされたように、これからのさまざまな情勢を鑑みながら、品川区全体の保育事業を見つめた上で対処をしていただきますようにお願いをしておきます。"},{"i":49,"speaker":"高橋（し）委員","text":"そもそものところなのですけれども、先ほど、応能型にすることのご説明があって、子ども・子育て新制度で応能負担だというお話だったと思いますが、そもそもこの施設は、就学前乳幼児教育施設でありまして、幼稚園でもなくというところなのですね。そこがちょっとよくわからなくて、幼稚園でないのに、幼稚園の保育料と同等にするというところが、この施設が一体どういう存在、先ほどちょっとご説明があったのですけれども、そこは少しご説明いただけたらと思います。"},{"i":50,"speaker":"竹田保育課長","text":"こちらのぷりすくーるは、国から幼稚園という形では認定は受けていないものですけれども、３歳から５歳という幼稚園と同時期のお子さんを預かる。あるいは、また幼稚園と同等程度の教育をするということで、品川区が独自に多彩なメニューで幼児教育の新しい姿といいますか、そういったものを模索しながら設立した施設だと考えております。"},{"i":51,"speaker":"高橋（し）委員","text":"どういうふうに運営されて、どういう成果が上がったというのはいいのですけれども、平成２８年４月１日からこの保育料でやるということは、その時点でも今の状態の幼稚園でもなく認定こども園でもないというか、そういった形で進んでいくということにつながるのではないかと思います。そこで平成２８年から新制度の中のどこかの施設、幼保連携の施設にしていくのか、それともそうではない施設にしていくのかということとつながっていくのではないかと思っています。その点はどうでしょうか。"},{"i":52,"speaker":"竹田保育課長","text":"先ほど申し上げたとおり、１０年前に品川区独自の新しい形ということでスタートしたのですけれども、その間、今回、新制度がスタートしたということもありますので、今後同じ形態でいくのか、あるいは新制度の内容を踏まえた施設にしていくのかということは、十分研究して、来年度以降のことを決めていきたいと考えております。"},{"i":53,"speaker":"高橋（し）委員","text":"ということは、そこでやっていくのですけれども、前にちょっとお聞きしたこともあるのですけれども、名称については、幼保連携認定こども園に類したものを使えるのは、半年間の猶予期間ということなのですが、そこについて今年途中でそういったことが迫ってきていることもあるのですけれども、それも含めて今後のこの施設がどうなるかというのは、保育料をこうしていくということにも絡んでくるので、その点についてはどうでしょうか。"},{"i":54,"speaker":"竹田保育課長","text":"新制度では、幼保連携型認定こども園の諸条件が示されたところなのですけれども、仮にそういったことを目指すときに、条件面だとか、例えば広さ、敷地の面積等、適合するものなのか、あるいはどうかということも詳細に検討しまして、あるべき姿については考えていきたいと思っております。"},{"i":55,"speaker":"高橋（し）委員","text":"すみません、では最後。\n新制度に向けてどういうふうにこちらを展開していくかということは、十分検討していただきたいと思います。"},{"i":56,"speaker":"飯沼委員","text":"１つ漏らしてしまったので。\n延長夜間保育の利用料についてお伺いしたのですけれども、条例によると、延長夜間保育利用料額が、１人１時間４００円で、新旧も同じ。あと、新しい短時間のところですか、保育時間内延長保育、ここのところも１時間４００円となっているのですが、ぷりすくーるのホームページを開いたら、延長夜間保育、延長保育と夜間保育と別々に書かれていて、延長が４００円で、夜間保育は８００円というふうになっていたのです。これが実際にどうなのか、これがまたこの改定でどう変わるのかというところを改めて教えてください。"},{"i":57,"speaker":"竹田保育課長","text":"従来、６時半、延長夜間保育については、委員おっしゃるとおり４００円ということで決めておりまして、今回、こちらの増額については、検討した結果、今後も引き続き４００円としたいと思っております。\nすみません、ちょっとホームページの部分のところの今、内容を確認できないのですが、延長夜間料金は、引き続き４００円で、利用時間帯は６時半から８時半までで、１時間が４００円ですので、２時間だと８００円というのが記載だと思います。"},{"i":58,"speaker":"飯沼委員","text":"ありがとうございます。\n延長だと１時間で４００円、夜間にかかると２時間で８００円になるということなのですね。はい、わかりました。\nぷりすくーるは延長夜間の保育料は、幼稚園の預かり保育や……、ここは保育園ですものね。区立の普通の保育園は、延長夜間保育利用料は段階に分かれていますよね。一律ではないですよね。やっぱりここは違うのだという考え方なのですか。４段階ぐらいに分かれていて、多分、１時間４００円は最高額と思うのですが、では、ぷりすくーるは階層を設けなくて一本でやってきたということでよろしいでしょうか。"},{"i":59,"speaker":"竹田保育課長","text":"委員ご指摘のとおり、保育園のほうは細分化されておりますが、ぷりすくーるについては一本化して４００円という形でわかりやすくしているところでございます。"},{"i":60,"speaker":"塚本委員長","text":"ほかにないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":61,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":62,"speaker":"浅野委員","text":"賛成します。"},{"i":63,"speaker":"飯沼委員","text":"意見を添えて反対をいたします。\n共産党としては、幼稚園も保育園もどの子も等しくよい環境で育てていきたい。また、保育料は父母負担があるわけですけれども、子どもの医療費の無料化と同じように、限りなく子育てにお金がかからない、そういった社会にしていきたいと思っています。ここは区立といえどもＮＰＯ法人で経営をしているということで、私立の幼稚園との関係がいろいろあるとは思うんですけれども、トータルで父母の負担が増えていくといったところで反対をします。そして、応能負担という国の考えを導入していますけれども、保育にかかる総額が増えていくと、必ず保育料にはね返っていくという意味では、これからやはりとまらず保育料が上がっていく、負担増になっていくという考えに基づいていますので、反対をさせていただきます。"},{"i":64,"speaker":"大倉委員","text":"賛成です。"},{"i":65,"speaker":"高橋（し）委員","text":"賛成なのですが、意見で。\nこの施設が０歳から２歳の保育料が保育園にということで、３歳から５歳が幼稚園にということで、この教育施設の性格が、０歳から５歳を預かっているこの施設の性格がはっきりしていないというか、新制度になったがゆえに、逆にそうでない存在になってしまったということがあるので、その点について、今後、新制度との関係をきちんと危惧して検討して進めていっていただきたいと思います。この議案は賛成です。"},{"i":66,"speaker":"塚本委員長","text":"それでは、これより第５９号議案、品川区立就学前乳幼児教育施設条例の一部を改正する条例について採決をいたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":67,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(3) 第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例"},{"i":68,"speaker":"塚本委員長","text":"次に、(3)第６２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":69,"speaker":"野呂瀬学務課長","text":"それでは、第６２号議案についてご説明いたします。\n本案は、品川区立の各小中学校に委嘱している学校医、学校歯科医、学校薬剤師が公務災害を被った場合の補償額を定める条例の一部を改正するものです。\n学校医等は、開業医や薬局など他に正業とする職を持つ非常勤職員であることから、別途、条例で補償基礎額を定めることになっております。この金額の算定基準は、都の基準額に準じておりまして、ほぼ毎年改定されており、今年度もその改定がございましたので提案するものでございます。\n本条例改正は、都立学校の学校医等公務災害補償条例を準用し、補償基礎額を平成２６年４月１日適用の第１条別表と、平成２７年７月施行の第２条別表に分けて２段階で改正を行い、第１条と第２条を併記することにより、過去に遡って公務災害補償申請があった場合に、補償適用上の不利益を被らないようにするためのものです。\n資料の１ページ目の中ほど、１の(1)として、補償基礎額の改定例を３つほど掲げておりますが、経験年数５年以上１０年未満の学校医および学校歯科医については、平成２６年４月１日から適用し、８,６００円を８,６１２円に、次ページに記載しておりますが、平成２７年の施行からは８,６１２円を８,７０９円に改正します。\nこの例では、双方とも単価アップのため問題はないのですが、例えば真ん中の経験年数１５年以上２０年未満の学校医および学校歯科医につきましては、平成２６年４月１日から適用し、１万２,９６０円を１万２,９７８円に、次ページに記載しております平成２７年７月の施行からは１万２,９７８円を１万２,９６９円に改正すると、新補償基礎額が９円下がることになります。このように新旧を比べて新しい補償基礎額のほうが下がっている対象者が一部おります。\n公務災害補償の遡及有効期間は２年間ですので、もしも２年間の間に遡って請求がされた場合、条例改正前に補償金額が下回ることがないように、付則を併記して経過措置を定め、補償適用上の不利益を被ることのないようにするものでございます。\nまた、その他の改正点として、１ページ目、１の(2)に記載のとおり、今回は博士課程の修了年数についても、都の条例が改正されたことに伴い、品川区においても同様の改正を行うものであります。\nなお、施行期日は公布の日といたします。"},{"i":70,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":71,"speaker":"石田（ち）委員","text":"今、説明していただいたと思うのですけれども、２段階で改正というのがどういうことなのかもう一回、すみません、言っていただきたいのと、これ、変わるのは金額だけの変化なのか伺いたいと思います。"},{"i":72,"speaker":"野呂瀬学務課長","text":"ちょっとわかりにくかったと思うのですけれども、毎年、改正は１種類だけなのです。２段階というのは、平成２６年４月の分につきましては、３ページの表は、新旧あるのですけれども、いずれにしろ新は全部単価が上がっているのですけれども、これは平成２６年４月１日から適用しますということです。それで、４ページなのですけれども、４ページは、一部単価が下がっているものが、例えば、先ほどご説明した学校医、学校歯科医の補償基礎額で、左から３番目の１万１,４２７円というのは、旧が１万１,４３５円だったものが１万１,４２７円と８円安く単価が下がっていたり、その右も旧と新を比較しますと９円安くなっていたり、この部分につきましては、単価が下がる分につきましては、前の平成２６年の上がっている分を適用する。それで、今申し上げた単価が上がっている分につきましては新しいほうの基準を適用するということで、これが２段階で改正する、遡及されたときに不利益にならないようにということでございます。その単価、補償の金額、ほとんどはこの金額が変わるということと、もう１つあわせて変わるところが、先ほど申し上げたのですけれども、３ページの備考のところに書いていたと思うのですけれども、今まで「医師及び歯科医師にあっては４年、薬剤師にあっては５年」というふうに書いてあった博士課程の経験年数を一律４年に改める、こういうところが改正点でございます。"},{"i":73,"speaker":"石田（ち）委員","text":"ありがとうございます。"},{"i":74,"speaker":"伊藤副委員長","text":"すみません、簡単なことで。説明ありがとうございました。３ページの新旧対照表のところで、医師と歯科医師に比べて学校薬剤師の方が上がっていますよね、金額がぐんと上がっているのです。医師、歯科医師は例えば１０何円の基準なのだけれども、この学校薬剤師だけが、例えば何百円とかの単位で上がっているのだけれども、単純にこれは何なんですか。わかれば教えてください。"},{"i":75,"speaker":"野呂瀬学務課長","text":"これは、公立学校の学校医に準じてと先ほど申し上げたのですけれども、そもそもこの東京都の条例自体が、東京都の人事委員会のほうで医師とか薬学の関係、いわゆる都の条例で医療職給料表がそもそもありまして、それに準じて東京都の学校医、学校薬剤師の単価も改正になるということですので、その都の人事委員会の給料表に準じたということになっております。"},{"i":76,"speaker":"伊藤副委員長","text":"言いたいことはわかりました。"},{"i":77,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来。"},{"i":78,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":79,"speaker":"浅野委員","text":"賛成します。"},{"i":80,"speaker":"石田（ち）委員","text":"賛成です。"},{"i":81,"speaker":"大倉委員","text":"賛成です。"},{"i":82,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":83,"speaker":"塚本委員長","text":"それでは、これより、第６２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例について採決いたします。\nお諮りいたします。\n本件は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":84,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(4) 第６３号議案 品川区立幼稚園条例の一部を改正する条例"},{"i":85,"speaker":"塚本委員長","text":"次に、(4)第６３号議案、品川区立幼稚園条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":86,"speaker":"竹田保育課長","text":"私からは、第６３号議案、品川区立幼稚園条例の一部改正についてご説明いたします。\n１、改正理由ですが、本年４月から施行されました子ども・子育て支援新制度におきまして、幼稚園保育料（１号認定子ども）について、子ども・子育て支援法施行令で定める額を上限に所得に応じた応能負担とするとされました。品川区では、平成２７年度は国からの詳細な内容についての明示が遅れ、区民への周知期間が短いことから、区立幼稚園の保育料は第一子の保育料を従来と同額といたしました。ただし、新制度にあわせて多子世帯の減免（第二子半額、第三子以降免除）については先行して適用いたしました。平成２８年度からは国基準額を考慮して応能負担とするため、全面的に改正する必要があると考え、ご審議いただくものでございます。\nなお、現行の月額保育料は一律８,０００円、入園料２,０００円となっております。\n２、改正内容ですが、1)国基準額および現行の私立幼稚園の園児保護者補助金の枠組みから、所得階層を以下の７区分とするものでございます。\n第１階層の生活保護世帯および第２階層の区民税非課税世帯については０円、第３階層は国基準額での第２階層と同額の３,０００円、第４階層は現行とほぼ同額の８,４００円、第５階層は第４階層と第６階層の保育料の差をなだらかなものとするため新設いたしました。第７階層につきましては１万６,０００円とし、最高額を現行保育料の２倍以内といたしました。\n2)国の新制度の考え方にあわせまして、入園料２,０００円を廃止したいと考えております。\n３、新旧対照表は別紙のとおりでございます。\n４、経過措置ですが、保育料の改定にあたり、1)平成２７年度在園児については従来の額と同額とする。\n2)平成２８年度新規入園児は、従来額と比較し保育料が上がる場合は、従来額から上げ幅を半額とする。\n以上のとおり経過措置を設けたいと考えております。\n５、施行日は平成２８年４月１日です。"},{"i":87,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑ございましたら、ご発言願います。"},{"i":88,"speaker":"石田（ち）委員","text":"さっきのぷりすくーるのほうも階層、先ほど所得を伺ったのですけれども、年収という形で答えられたのですが、それと同じにはなってくると思うのですけれども、割合、人数のところをこちらも聞かせていただきたいと思います。\nそれと、やはり段階をつけた考え方というのは、ぷりすくーると同じになってくるのかを伺いたいと思います。"},{"i":89,"speaker":"竹田保育課長","text":"まず、所得階層でございますが、割合でございます。第１階層が０.３％、第２階層が５.９％、第３階層が９.１％、第４階層が３５.９％、第５階層と第６階層が合わせまして８.４％、第７階層が３９.６％となっております。第１から第４までの階層を足しますと５１.２％ということで、約半分の方が現行よりも下がる、あるいはほぼ同額という形になっております。\nそれで、保育料の考え方でございますが、ぷりすくーるにつきましては、品川区独自の幼児教育施設ということで、私立幼稚園の保育料を参考に設定いたしました。今回の区立幼稚園につきましては、私立幼稚園とは違う独立の運営をしておりますので、現行の保育料を参考に改定をいたしました。"},{"i":90,"speaker":"飯沼委員","text":"今、階層別の割合をお伺いしたのですけれども、この表でいくと、第４階層が８,４００円に上がるということで、ここからすると、今ちょっと計算したのですけれども、８３.９％の方が現行よりも保育料が上がると、こういった捉え方でまずいいのかどうか、１点です。\nあと、幼稚園のところも預かり保育をやっています。この基本の保育料以外に、保育園のように前後お仕事をしていらして、預かり保育を利用すれば金額がかさみますよね。預かり保育の中身を少し教えていただきたいのと、区立の幼稚園というのは、私立の幼稚園のように諸経費というのはかからないのかどうか。かかるのだったらどのくらいかかっているのか、それも教えてください。"},{"i":91,"speaker":"竹田保育課長","text":"まず、上がる方の割合でございますが、第４階層までをほぼ同額と考えれば、第５、第６、第７の階層の方が４８％というところでございます。約半分の方が上がるというところでございます。\nそれから、今回、保育料を見直ししましたので、預かり保育料についても検討しましたが、ご負担増になることもありますので、基本的には預かり保育料は現行どおりというところで考えているところでございます。\nそれから、諸経費につきましては、すみません、ちょっと正確な金額は持ち合わせてございませんが、ご負担のないようにしているところでございます。園服等の諸経費が発生するものでございます。"},{"i":92,"speaker":"飯沼委員","text":"今、預かり保育は現行どおり変えないといったお答えをいただいたのですが、どのくらいの金額になっているか、ざっと教えていただけますでしょうか。"},{"i":93,"speaker":"竹田保育課長","text":"すみません、変えないと申し上げたのではなくて、今回はご提案させていただいておりませんということです。"},{"i":94,"speaker":"飯沼委員","text":"今回は提案しない。"},{"i":95,"speaker":"竹田保育課長","text":"はい。それから、預かり保育料のざっとということでございますが、施設によって預かり保育料は異なっておりまして、単独の支援であります城南、伊藤、八潮わかばについては１日４００円、浜川については１日６００円、それから幼保一体施設もそれぞれ異なっておりまして、第一日野が１日６００円、平塚すこやか園が１日７５０円、のびっこ園台場が、就労支援型につきましては１日６００円、子育て支援型については１日７００円でございます。"},{"i":96,"speaker":"飯沼委員","text":"ありがとうございます。\n諸経費は園服だけということなのですけれども、預かり保育のところは、今、４００円から６００円、７５０円、幼保一体のところ、単独のところ、形態によって違うわけですけれども、これ、日額ですよね。なので、保育料のところは保育園保育料と比べると比較的低く抑えられてはいますけれども、結局、利用者の立場で１日の保育時間が長くなれば、当然この預かり保育、１日４００円でも、２０日利用するとプラス８,０００円になるし、６００円だったらもっと１万２,０００円になってしまうとか、保育料よりも預かり保育のところのほうが額が多くなってしまう、そういった実態もあるというところで捉えていいのでしょうか。もう一回確認です。"},{"i":97,"speaker":"竹田保育課長","text":"預かり保育は日額で設定しておりますので、利用日数に応じて、利用日数が多くなれば月単位で利用料は増えるということでございます。\nそれから、諸経費は園服等でございます。\n預かり保育については、適正に運営していきたいと考えております。"},{"i":98,"speaker":"塚本委員長","text":"もう一度。ちょっと最後のほうがよく聞こえなかったので、もう一度。"},{"i":99,"speaker":"竹田保育課長","text":"預かり保育については、十分保護者の方のご意見を聞きながら、適正な運用をしていきたいと考えております。"},{"i":100,"speaker":"金子子ども未来部長","text":"預かり保育のお尋ねでございます。今、課長が申し上げたような現状でありますが、金額の種類が４００円、６００円、７５０円、５５０円とか、かなり多岐にわたっています。しかも、幼稚園の場合には、給食費が私費扱いになるので、これによっても保護者の方から徴収する金額がかなり変わってくるということで、非常に細分化、極端に言うと、一人一人違うというふうなことにもなっています。\nそういう意味では、かなり事務負担が大きいので、そういった点、また、今回、新制度になりまして、さまざまなものが変更になってきていますので、これについてはやはり見直す必要があるかなというふうには考えておるところですけれども、今回は基本の保育料だけということでご提案させていただいているところでございます。"},{"i":101,"speaker":"浅野委員","text":"区立幼稚園で、まず、先ほどのお金の話なのですけれども、保育料の合計です、ぷりすくーるのところでもお伺いしましたけれども、今回の改定によって、歳入というのでしょうか、どのぐらいの変化があるのか、ほとんど変わらないのかというところについて教えていただきたいと思います。\nそれと、この条例の施行日が平成２８年４月１日になっていますが、当然、周知期間が必要かと思うのですが、これはどのような形で、いつごろから区民の方に周知をされるのか、計画があれば教えてください。"},{"i":102,"speaker":"竹田保育課長","text":"まず、区全体の歳入の状況でございますが、今現在の保護者の方の所得状況が変わらないと仮定すれば、現在より約４０％の増になると予定しております。\nただ、高所得の方々が私立幼稚園等を希望された場合には、想定よりも少なくなることも考えられます。\nそれから、周知方法でございますが、今定例会で議決をいただきました後に、幼稚園の募集期間が秋口でございますので、募集までの間に募集要項に記載したり、幼稚園に掲示物を張ったり、さまざまな媒体を通して周知していきたいと考えております。"},{"i":103,"speaker":"浅野委員","text":"４０％増になるということで、実際にスタートしてみないと、この変化はなかなかわからないと思うのですけれども、もし余裕があると言ったら怒られてしまいますけれども、区立幼稚園のさらなる質の向上というのでしょうか、そういうことも心がけていただきたいし、また、設備についても、できる限り子どもの環境アップにつながるような、そのような手もできれば分けていっていただきたいと思います。これは要望ですけれども、もう考えられているところがあるかと思いますけれども、そういう意味では、やはり区立の幼稚園、皆さんに喜んで来ていただけるような、そういうような取り組みを進めていっていただきたいと思います。お願いします。"},{"i":104,"speaker":"竹田保育課長","text":"今回の区立幼稚園の保育料の改定は、前回が平成１３年４月に行われて、これまでの間、保育料は据え置いてまいりました。この間にも平成１４年に品川区初の幼保一体施設二葉すこやか園、それから平成１８年にのびっこ園台場、平成２２年に第一日野すこやか園、平成２３年に北品川すこやか園、平成２５年に平塚すこやか園と幼保施設の建設を通して幼稚園教育の充実に努めてまいりました。今後も保育の質の向上に向けて全力で取り組んでまいりたいと考えております。"},{"i":105,"speaker":"高橋（し）委員","text":"これ、先ほどのぷりすくーるのところと同じようなお話になっているのですけれども、区立の幼保一体施設があるかと思います。その中に同じ年齢で保育園に行っている子と、幼稚園に行かれている子がいるということで、幼保一体施設とは言っていますが、この保育料の点で、明らかに新制度のもとでも、ここの体制は幼保一体に対しては異なった形になっているのですが、先ほどのぷりすくーると同じように、区立の幼保一体施設の今後といいますか、これも現行、その中に幼稚園があるということで、どういった展望なのかということと、先ほどもちょっと聞き取れなかったのですが、幼保一体施設という名称自体、いろいろなところで使っていますけれども、これを今後使っていけるのかいけないかということを。"},{"i":106,"speaker":"竹田保育課長","text":"先ほどのぷりすくーるのほうとの重複になりますけれども、それぞれの施設、幼保一体施設に仮に移行する場合に、条件面等はどうなのかということをしっかり調査しまして、また、保護者の方の幼稚園に預けられる方のお考え、ニーズ、あるいは保育園に預けられている方のニーズもそれぞれ十分お聞きしまして、ご要望にお応えできるような施設運営に努めてまいりたいと考えております。\n名称の件でございますけれども、今のところ、現行どおりで運営していく場合は幼保一体施設ということで考えております。"},{"i":107,"speaker":"高橋（し）委員","text":"私のほうが勉強不足なのかもしれませんけれども、幼保一体に類したというか、そういうものを使えないということですが、正式なこちらの区立の幼保一体施設の名称は、二葉すこやか園だとか、のびっこ台場だとかという形でいくということですか。私の勉強不足で、幼保一体施設という名称は、幼保連携型認定こども園に類したものは使えないという条文があったと思うのです。すみません、もし私が違っていたら……。"},{"i":108,"speaker":"竹田保育課長","text":"ご指摘のとおり、幼保一体認定こども園という言葉は使えないわけですけれども、幼保一体施設という名称は使用可能と考えておりますので、現行どおりでいく場合は、こちらの名称を引き続き使っていきたいと考えております。"},{"i":109,"speaker":"伊藤副委員長","text":"何点か質問させてください。\nこの幼稚園保育料の改定の中で、消費税が３％上がっていますね、当たり前ですけれども。その３％については改定していなかった、つまり、保育料に上乗せしていなかったのでしょうかという確認と、それから、保育料の減免措置、例えば確か第二子は半額だとか、そんなことがあったと思うのですけれども、その減免の措置を改めて教えてください。\nまずその２つ。"},{"i":110,"speaker":"竹田保育課長","text":"先ほど申し上げましたが、前回の保育料改定が平成１３年４月ということで、この間に委員おっしゃるとおり消費税のアップ、あるいは人件費、運営費、工事費等の高騰があったわけですけれども、この間、保育料に関しましては据え置いてまいりました。\n保育料の減免については、少子化に対応できるように、第二子半額、第三子免除という形をとっております。"},{"i":111,"speaker":"伊藤副委員長","text":"ありがとうございます。\nもう少し勉強してきますと、この区立の幼稚園の運営に関しては、国庫補助が入ったりとか、都の補助金がないということも確認しました。つまり、品川区の単費で幼稚園が運営されているということはわかってきました。\nその中で改めて決算を勉強させていただくと、平成２５年度の歳入、つまり、保育料等々の総額は約８,９００万円。それから歳出、これは職員の給与費と事業費を合わせて４億６,０００万円というふうに計算したのですけれども、数字が正しいでしょうかという確認と、それから差額が約３億７,０００万円、これがつまり品川区の一般財源から充当されていると思うのですけれども、この数字の確認を改めてお願いします。"},{"i":112,"speaker":"竹田保育課長","text":"平成２５年度の決算ベースでございますが、歳入のほうが、幼稚園保育料、手数料、国庫補助、預かり保育料等を足しまして約８,９００万円。歳出のほうが、職員給与費、あるいは事業費を足しまして約４億６,０００万円。歳入と歳出の差が約３億７,２００万円という形でございます。"},{"i":113,"speaker":"伊藤副委員長","text":"確認ですけれども、歳入の中に国庫補助が入っていると聞いたのですけれども、これは何ですか。その確認と、それから、この３億７,０００万円が一般財源で補填されているからこそ、この保育料で運営されていると思うのだけれども、その確認をお願いします。"},{"i":114,"speaker":"竹田保育課長","text":"先ほどの国庫補助につきましては、生活保護や非課税で減免される方の分が補助されておりまして、平成２５年ベースで申し上げますと、１０万４,０００円というふうになっております。"},{"i":115,"speaker":"伊藤副委員長","text":"先ほど、この改定で保育料が２,３００万円ぐらいアップすると言っていましたけれども、保育料の改定が２,３００万円増と聞きましたけれども、そうすると、単純に平成２５年のベースで考えますけれども、８,９００万円に２,３００万円の上乗せをされたとしても、つまり、品川区からの一般財源の投入はあるということの確認をお願いしたいと思いますが、その確認と、それから、唐突ですけれども、中学生の税についての作文があるのです。これは納税貯蓄組合連合会等々が品川区のまさに中学生に税の作文を募集しました。この中でやっぱり税金のすばらしさとか、それから、使われ方の内容とか、いろいろ書かれているのです。\n例えば、ある小中一貫校の生徒が、日本では火事のとき、通報するだけで消防車が駆けつけ消火してくれるが、世界では目の前で火事が起きていても、消火の前に払うお金を相談しなければならない国があると聞いて驚いたと。それから、これも同じある中学生の作品ですけれども、財務省の「高齢者１人を現役何人で支える？」の資料では、２０１３年で２.３人、２０２５年では１対１で支える結果でした。このまま現役世代の人数が減ってしまっては現役世代の負担が大きくなってしまいますという表現。それから、この子は、その機会を見つけるために消費税を引き上げたりすることに挑戦することは大事だと僕は思いますという表現まであるのです。つまり、一貫して書かれていることは、これからさらに進む少子高齢化社会の財源、社会保障の財源が非常に厳しいので、税金についてもっと考えていくということの意見につなげていかれるのです。\nだから、私はこういう税金の使い方について、もちろんこのことについて反対するわけではないのだけれども、一般財源を３億７,０００万円投入したいと思う。だから、その使われ方について、やはり先ほど言ったように公平性、公明性、同時にしっかり担保していかないといけないと思うのだけれども、この税金が投入されているからこそ、保育料も安くなって、そうではない私立の幼稚園へ行かせる子どもたちがいるだろうし、それから在宅で子育てしている方々もいらっしゃる。この方々だけが財源が投入されているからこそ安い保育料で保育を受けられるわけです。だから、そういうことまできちんと税金の使い方を説明をしていただいた上で、ご理解して納得をしていただかないことには、中学生の言う社会の公正なり、税の公正ということは担保できないと思うので、ちょっと論点がずれるのかもしれないけれども、これだけの税金を投入しても幼稚園を運営していく品川区の考え方を改めてお聞かせください。"},{"i":116,"speaker":"竹田保育課長","text":"まだ試算でございますが、今回の保育料改定に基づきまして、約１,９８０万円の収入増というふうに考えております。先ほどご案内しました平成２５年ベースでは、３億７,０００万円ほど一般財源から持ち出しているということなので、今回の保育料改定によって一般財源のごく一部を減らすことができるという状況でございます。\nあと、利用者の方、あるいは子育てされる方の中には、私立や在宅で子育てされている方、あるいはお子さんを持たないご家庭、社会の中にはさまざまな方がいらっしゃいますけれども、一般財源を投入する以上は、広くいろいろな方々にご理解いただく必要があると考えております。少子高齢化の社会に適切に対応していけるような保育料を今後も考えていきたいと考えております。"},{"i":117,"speaker":"伊藤副委員長","text":"まとめますけれども、中学生の税の作文に相当書かれているのですけれども、少子高齢化社会の進展と税の使われ方について、非常に鋭い観点で書かれています。これから税金は社会保障に使われていくものがどんどん増えていくことは目に見えているわけなのです。だから、このことについて、私ども反対するわけではないのだけれども、だけれども、税金の投入のバランス、公平性というものについては、まさに皆様方が、理事者の方々がしっかり考えていかないと、さまざまなところで大きな不満が出てくる可能性があるので、そのことには重々注意をしていただいて対処していっていただきますようにお願いしておきます。"},{"i":118,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、初めに、自民党・子ども未来。"},{"i":119,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":120,"speaker":"浅野委員","text":"賛成です。"},{"i":121,"speaker":"飯沼委員","text":"意見を添えて反対をいたします。\n１つには、第３段階が３,０００円ということで下がるということは歓迎いたします。しかし、先ほどのご答弁の中にも、８割強の方が値上げに、負担増になっていくといった中身、そして、大もとにあります応能負担が公平とは考えておりません。税金というのは負担能力に合わせて納めているわけですけれども、利用というのは、どの子も大事にしていきたい、子育てを区民全体、社会全体で支えて保障をしていく有効な税の使い方であると思っていますので、もっと税負担をすることで子育ての保育、幼稚園でもそうですが、負担を減らしていく、限りなく無料化に近づけていきたい、これが基本の考えですので、今回の負担増に対しては反対をいたします。"},{"i":122,"speaker":"大倉委員","text":"賛成です。"},{"i":123,"speaker":"高橋（し）委員","text":"賛成です。\n今、税金のお話もありましたとおり、やはりかなり保育料が上がる方も中にはいらっしゃるので、十分にご説明していただいて、今、教育内容も充実していると思うのですが、さらに充実した保育をしていっていただきたいと思います。"},{"i":124,"speaker":"塚本委員長","text":"それでは、これより、第６３号議案、品川区立幼稚園条例の一部を改正する条例について採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":125,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(5) 第５５号議案 平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":126,"speaker":"塚本委員長","text":"次に、(5)第５５号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":127,"speaker":"品川庶務課長","text":"それでは、本定例会に付議いたします第５５号議案、平成２７年度品川区一般会計補正予算の教育委員会分につきましてご説明いたします。\nまず、歳出でございますが、資料の２４ページをお開きください。上段、７款教育費、１項教育総務費、３目教育指導費につきましては、９５０万８,０００円を追加いたしまして、１１億４,７２７万１,０００円とするもので、右側２５ページ上段をご覧いただき、プラン２１推進事業として、オリンピック・パラリンピック教育推進事業、理科観察実験支援事業、日本の伝統・文化発信能力育成事業の特色ある教育活動経費、および国際理解教育として、英語の実践的なコミュニケーション能力を身につけ、総合的な英語力の向上を図るため、８年生を対象に、タブレットやパソコンを利用して外国人講師と英会話のマンツーマンレッスンを行うオンライン英語レッスン経費を計上しております。\n以上によりまして、教育総務費の計を５５億４,３９３万２,０００円とするものでございます。\n次に、２４ページ下段をご覧ください。２項学校教育費、１目学校管理費につきましては、８９３万３,０００円を追加いたしまして、７８億７,２３８万５,０００円とするもので、右側２５ページ下段をご覧いただき、教材教具費として、６年生から９年生の受験希望者に対して、実用英語技能検定の受験料を全額助成することで、英語教育の到達度を数字で確認し、さらなる英語学習の意欲を育てるものでございます。\n以上によりまして、学校教育費の計を１１１億３３５万１,０００円とするものであります。\n続いて、歳入でございますが、１０ページをお開きください。\nページ上段、１３款国庫支出金、２項国庫補助金、５目教育費補助金において、４４万７,０００円、およびページ下段、１４款都支出金、２項都補助金、６目教育費補助金の４４万７,０００円につきましては、理科観察実験支援事業の特色ある教育活動経費の補助がございます。\n次に、１２ページをお開きください。ページ中段、１４款都支出金、３項都委託金、５目教育費委託金につきましては、オリンピック・パラリンピック教育推進事業および日本の伝統・文化発信能力育成事業の特色ある教育活動経費の補助として、５５０万円を計上してあります。"},{"i":128,"speaker":"渋谷指導課長","text":"では、オンライン英語レッスンにかかわる部分について補足の説明をさせていただきたいと思います。資料のほうをご覧いただければと思います。\nこの事業は、小学校の英語教育の充実を図っていく中で、さらにグローバル人材育成塾、イングリッシュ・キャンプ、語学派遣というふうに、中学校英語で勉強してきた子どもたちの英語の学びの欲求に応える授業を展開してまいりましたが、さらに英語の授業そのものの質の向上を目指すために、オンラインによる英会話レッスンを英語科の授業の中に取り入れるというものでございます。\n具体的な事業内容につきましては、まずモデル校２校、大崎中学校、浜川中学校で、月に２回、１回２５分のオンラインによる英会話の授業を導入するというものでございます。\n内容につきましては、英語の教科書をベースにした新たな教材を開発していただいて、子どもたちが一人一人ネイティブの現地の方たちとパソコンを通して英会話のレッスンをするというものでございます。９月から月２回、７カ月間、一人当たり３５０分、約６時間弱をマンツーマンで外国人の方とお話をする機会を持つということで、これは大変価値のある体験になるのではないかというふうに思っています。\n今回、モデル事業として出たのは、実際、３０数人が実際に教室でオンラインでつないだときにうまくいくのかどうかということ、また、一人一人の英語講師とうまくコミュニケーションをとったりすることができるかなどということを検証しまして、この後、今後の事業の拡大を考えていきたいというふうに思っているところでございます。"},{"i":129,"speaker":"野呂瀬学務課長","text":"それでは、後段の英検の公費助成について補足説明させていただきます。資料をご覧ください。\n目的、内容は、先ほど庶務課長が言ったとおりなのですけれども、いわゆる英検助成、公費助成を通じて英語学習の意欲をより高めるということです。事業内容のところに表があるのですけれども、いわゆる算出根拠といたしましては、今、７年生から９年生まで４,８００人ほどいます。そのうち、ここで中学全体の５級が１割、４級が２.５割、３級は５割、準２級は１.５割、これを全部足すと１０割になる。これはレベル別に見ますと、今まで、地域で、各学校でやっていた受験が大体このレベルの率で受けていたということです。７割というのは、今まで、昨年までは私費で学校で受けていたものが大体４割ぐらいだったと聞いていますので、公費助成にすれば７割ぐらいに上がるのではないかという想定で算出したものでございます。\nあわせて一番上に載っていますけれども、６年生、５級、約２００人というのは、今まではどこも小さいときはやっていなかったらしいのですけれども、これに伴って、６年生につきましても、希望者のみ、１割程度を見込んで、５級の試験を希望者については受けていただくということで算出して、全体で８９０万円余の額を公費助成として計上しているものでございます。"},{"i":130,"speaker":"伊崎子ども育成課長","text":"それでは、私から、引き続きまして、子ども未来部関連についてご説明をいたします。１６ページをお開きください。\n３款民生費、２項児童福祉費、１目児童福祉総務費につきましては、１,５３０万円を追加し、４２億７,９８７万２,０００円とするものでございます。\n右側１７ページの説明欄をご覧ください。まず、次世代育成支援対策費追加分として、子育て支援情報発信アプリの導入でございます。これは保護者の方がスマートフォンなどで必要な子育て情報の取得を容易に行うためのアプリなどの開発、構築でございまして、委託料９００万円でございます。\n次に、１９ページをご覧ください。１９ページ上段、待機児童解消対策費追加分としまして、公園における保育園整備を検討するために、施設計画検討経費として、委託料６３０万円を計上しております。\n続いて、１８ページ、２目児童措置費でございます。児童措置費につきましては、１３２万円を追加し、１２２億１,２８２万５,０００円とするものでございます。\n右側１９ページをご覧ください。説明欄にございますが、児童保育委託追加分、各種児童保育委託として、医療的ケアを必要とする障害児をもつ保護者に対して、就労支援の一環として保育施設に通う保育料の一部を助成するため、要医療障害児支援事業として、負担金補助および交付金１３２万円を計上しております。"},{"i":131,"speaker":"今井待機児童対策担当課長","text":"私からは、補足説明といたしまして、１９ページにございます待機児童解消対策費についてご説明申し上げます。\n口頭ではございますけれども、本件は、現在、国家戦略特区の追加規制緩和策といたしまして、都市公園内におけます保育所設置の検討が進められていることから、総合的な待機児童対策の１つとして、都市公園を含みます区内の公園におきまして、保育園整備における検討を進めるものでございます。\nこちらは委託費として、先ほどご説明しましたとおり、６３０万円を計上しているところでございます。"},{"i":132,"speaker":"竹田保育課長","text":"私からは、１９ページ、要医療障害児支援事業について補足説明させていただきます。\nこちらは、医療的なケアを必要とする障害児に対する保育料の助成をするものでございます。現状では、保育園の入園を希望する心身障害のある児童や、心身の発達の状態から同様の配慮を必要とする児童については、保護者の就労を支援することから、当該児童が集団保育が可能な場合には、発達上、有益であるという場合、積極的に受け入れてまいりました。しかし、医療的なケアを必要とするケースについては、単なる職員の加配にとどまらず、看護師などの専門職の加配や保育士に対する痰吸引等の医療的な研修も必要とすることから、対応してきませんでした。\n事業内容でございますが、医療的なケア（痰吸引、経管栄養、導尿等）を必要とする障害のある児童の保護者に対する就労支援について、保育施設を利用する場合にかかる保育料の一部を助成するものでございます。\n助成の対象者でございますが、品川区が行う特別支援保育審査会に基づいて開催されます特別支援保育利用調整会議において、医療的ケアが必要なことを理由に認可保育園の入園を不承諾となった者の保護者を対象といたします。\n助成金額につきましては、重症心身障害者とそれ以外に分けまして、所得対象ごとに区分し、助成いたします。詳細はお手元の資料のとおりでございます。"},{"i":133,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":134,"speaker":"石田（ち）委員","text":"医療的なケアを必要とする障害児に対する保育料助成について伺いたいのですけれども、この保育施設というのは、どういう、認可保育園とか幼稚園とかあると思うのですけれども、保育施設というのは何を差しているのかということと、あと、助成の対象者を審査会に基づき開催される特別支援保育利用調整会議においてということですけれども、この会議体はどんなメンバーで構成されているのか伺いたいと思います。\nそれと、助成金額が所得階層ごとに区分されているのですが、これは何を基準にこういう階層区分とされたのかを伺いたいと思います。"},{"i":135,"speaker":"竹田保育課長","text":"対象施設でございますが、まだ医療的ケアを必要とするお子さんを受け入れる施設がごくごく小数でございますので、そういった施設を対象に、預けられるお子さんを対象にしていくものですが、それは認可施設あるいはされていない施設を含めまして、預け入れが可能な施設に対して助成していくものでございます。\nそれから、会議体でございますが、この会議体については、子ども未来部長を筆頭に、保育課長あるいは係長、それから園長等によりまして構成されている要綱に基づく会議体でございます。\nそれから、助成区分でございますが、先行して実施しております杉並区を参考に今回の助成区分を設置したものでございます。"},{"i":136,"speaker":"石田（ち）委員","text":"そうすると、区内にはそういう施設がないということですね。それで、杉並区を参考にということで、この杉並区の施設はどういった施設なのか教えていただきたいと思います。\nそれから、そういった医療ケアが必要なお子さんというのは、今現在、どれくらいいるのかお伺いいたします。"},{"i":137,"speaker":"竹田保育課長","text":"杉並区で実施されてございます施設は、こういった医療ケアの必要なお子さんに特化した施設と聞いております。\nそれから、必要とする子どもの数ですが、昨年のものを参考に申し上げますと、特別支援保育利用調整会議において、医療的ケアが必要との理由から集団保育に適さないと判断した児童は３名でした。"},{"i":138,"speaker":"石田（ち）委員","text":"この中のお一人のお母さんから私も相談を受けたのですけれども、何とかならないかと、区にはお願いしてきて、なかなか保育園も見つからない中で、杉並区のほうで特化した施設というところも見つけたということだったのですけれども、区が把握している範囲で、こういった医療ケアが必要な子を受け入れる保育園というのは、他区ではどれくらいあるのかというのは、区内にないわけですから、そういったお母さん方に残念ながら区内にはないけれども、こういったところがあるという紹介などはされているのかどうかを、まず聞かせてください。"},{"i":139,"speaker":"竹田保育課長","text":"こういった医療ケアの必要なお子さんを受け入れるというのは非常に難しいことと言われております。それで、２３区内では、私どもで把握しているのは杉並区と、あと横浜のほうにもそういった施設があるということで把握しております。\nそれから、周知しているかということなのですけれども、やはり医療的ケアが必要なお子さんは、ご自宅でみていただくことが最善だと考えておりますので、特段の周知はしておりませんが、就労支援の観点から、必要とされる保護者の方には助成をしていきたいと考えております。"},{"i":140,"speaker":"石田（ち）委員","text":"ぜひ、区内にこういった施設がないのであれば、そういった他区に、また他県にあるというのは周知していただきたいと思いますし、このお母さんもおっしゃっていましたけれども、こういった対応がされたのは本当にうれしいと。でも、やっぱり区内にあれば一番いいということだったのです。区内でこういった施設を運営していくということは、検討されたのでしょうか。それで、またどう考えているのかを伺いたいと思います。"},{"i":141,"speaker":"竹田保育課長","text":"先ほども申し上げましたけれども、医療的なケアを必要とするお子さんをお預かりするというのは、非常にリスクのある難しいことだと考えておりますので、通常の保育園ですぐに実施するということは難しいと思っております。\nただ、成長する中で障害程度が改善されて集団保育になじむような、発達とともになじんでいくということも考えられますので、そのお子さんの成長を見ながら、集団保育が可能となれば既存の保育園でも受け入れていきたいと考えております。"},{"i":142,"speaker":"石田（ち）委員","text":"本当にこういった受入れ先がないというところで、諦める方のほうが多いと思うのです。ですので、この保育料助成は大きな一歩だなと評価したいと思うのですけれども、ぜひ区のほうでもこういったお子さんの対応をできるように、先ほども言いましたけれども、なかなか進まない難しいという状況もありますけれども、他区にあるという点をぜひ周知していただきたいと思います。"},{"i":143,"speaker":"飯沼委員","text":"まず、１９ページの待機児童解消対策の公園のところに保育園をという中身なのですが、６３０万円で委託ということなのですけれども、どういう中身を委託するのかというところと、どのような事業者がこういう委託を受けるのかを教えてください。"},{"i":144,"speaker":"今井待機児童対策担当課長","text":"公園の整備にあたりますので、こちらは、例えば公園の地下埋設物ですとか、あとは実際にはどのような広さ、または近隣の状況も踏まえまして調査をしていく予定でございます。\n実際には、公園で開設できるところを少し絞りまして、最終的には開設できるレイアウトぐらいまでは絞っていきたいというふうに思っておりますので、今、事業者として想定しておりますのは、実際には施設整備関係の業績が優れた委託業者という形で、コンサルを考えております。"},{"i":145,"speaker":"飯沼委員","text":"ありがとうございます。\n以前いただいたプレス発表に、９０名程度の１カ所で１,０００m2とあったのですけれども、１カ所で限るわけではないですよね。最適地を探していくという捉え方でいいのか、それが１点。\nあと続いて質問をさせていただきますけれども、オンライン英語レッスンの資料を出していただいたのですけれども、これ、おもしろいというか、あまり普通にはというか、なかなか普通には発想できないような中身なのですけれども、このことで今の現状の子どもたちが英語が好きになるのかどうかというのが一番のポイントだと思うのですが、そこのところと、どこからこのような発想が出てきて、どのような経緯で計画されたのか、また、その中に現場の意見がどう反映されているのかを教えてください。"},{"i":146,"speaker":"今井待機児童対策担当課長","text":"施設概要としましては、公園ということで、今、実際に国家戦略特区の施設の基準というのですが、そういうふうな緩和の内容がまだ明らかにされておりませんので、一応モデルとしまして施設概要を定員９０名という形でお出ししているところですが、１カ所に限らず、一定の基準を満たした公園については、全て調査はしていきたいというふうに思っております。"},{"i":147,"speaker":"渋谷指導課長","text":"オンラインについてのご質問です。まず、好きになるのかというところが一番のポイントで、小学校から英語学習を導入していて、一番注意しなくてはいけないのは英語嫌いにしないということだというふうに思っています。子どもたちが、できる、わかるという、そういう成就感の積み重ねがこういった学習を本当に好きになる大きなきっかけになるのではないかというふうに思っております。したがいまして、こういう経験をすることは非常に有効だと考えております。\nそれから２点目のどこから発想がということでございますが、基本的には教育委員会事務局は、さまざまな業者の方から、さまざまなご提案をたくさんいただいているところでございます。そういった中で、今回は、ＩＣＴのトータル学習システム、タブレットを導入したところで、学研と事業を組んでいまして、もともとは学研の方からこんなものがあるのだけれどもどうだというようなことの１つとしてご提案いただいたところでございます。\n現場の意見はということでございますが、実際に導入を検討するにあたって、モデル校の英語の先生等々とも話をさせていただいて、ぜひこれは非常にいい取り組みだというようなことで、現場の先生方のご意見も十分反映させながら、この補正予算に提出させていただいたという経緯でございます。"},{"i":148,"speaker":"飯沼委員","text":"具体的なことも幾つかお伺いしたいのですけれども、この２５分の月２回、７カ月ということなのですが、この時間は通常の英語の時間からとるのかどうか、それが１つと、あと、英会話のことで詳しい人に聞いたら、フィリピンはかなりなまりが強いということを聞いたのです。子どもたちが聞き取るのになれるのに時間がかかるのではないかという意見が出たので、その点が１つ。あと、２５分間の使い方なのですが、英語の先生はいらっしゃいますよね。そこの中で子どもたちがタブレットに向かってフィリピンの方とコミュニケーションをとるわけなのですけれども、これが同じ人とつながるのかどうか、７カ月間、同じ人とつながっているのかどうかということと、あと、子どもの能力はものすごく違いますよね。英語の教科の先生は十分そのクラス全体を把握しながら授業を進めているわけですけれども、２５分間、タブレットに向かって異国の人とコミュニケーションをとるわけなのですけれども、子どもたちの能力の差というのか、そういうものに十分合わせて行われるのかどうかというのと、その指導員の方の身分とか資格、英語の教師だったら教員としての訓練を十分受けているのですが、その辺の疑問点はどうかなと思ってお伺いいたします。"},{"i":149,"speaker":"渋谷指導課長","text":"まず、２５分間の使い方ということでございますが、基本的には先ほどもちらっとご説明しましたが、一般のオンライン英会話ですと、新聞記事だったり、雑誌だとかでフリートーク中心に時間を積み重ねていくという形でございますが、中学校の授業の中で導入をするということでございますので、教科書を、例えば教科書で受動態を勉強したら、受動態の構文に基づくものを材料に生徒とやりとりをするという形になります。\nなまりとか、聞き取りとかという問題でございますが、基本的に今のオンライン英会話は非常にたくさんいろいろな民間の企業等々で導入されています。特にフィリピンは人件費が安いということで導入実績が多いですが、実際、英語公用国でありまして、今、世界のコールセンターと言われているフィリピンのところで、民間企業の研修等々で実績のあるところを選んで導入するということで、この部分については学研編集部が現地のほうに行って、発音スキルとか、文法スキルなどをチェックした安心できる講師を確保していただくということになっています。\nしたがいまして、今回のモデル事業もそういった実際に講師がどの程度の質なのかということを、私どもも実際に子どもたちのやりとりの中で確認させていただいて、しっかりと見極めていきたいというふうに思っています。\nそれから、同じ人間がずっとやるのかというと、必ずしもそうはならないということでございます。ただ、オンライン学習というところの最大限のメリットは、学習履歴をタブレットなりパソコンなりに残すことができるということですので、そういった学習履歴に基づいて子どもの一人一人の能力差に応じた指導ができるところがまさに強みだということでございます。したがいまして、子どもの能力差にどう対応するのかというのは、前回の子どもの学びがどのくらいの段階にあるというものを向こうの講師が把握した上で、一人一人に応じた指導を、この子は苦手な子だから易しめにとか、画面のやりとりだけではなくて、タブレットですから、わからなかったりすると、ボタンを押して向こうに知らせたりだとかと、そういう仕組みを用意しているというふうに聞いておりますので、そういうところで能力差に応じて英語が嫌いにならずに適切な指導ができるような体制を整えているということです。\n指導者の資格については、今ご説明したとおりでございます。"},{"i":150,"speaker":"飯沼委員","text":"それぞれありがとうございます。\nとにかく、せっかく新しいことを取り入れて英語が嫌いになっては困るので、楽しくやっていただきたいなと思うのと、ぜひ新しい試みを導入したときには、現場の教員の方々の意見、当該のモデル校はもちろんですけれども、その他の先生たちの意見も十分反映させて、あと、ぜひ検証、計画を実践してどうだったのかという検証をしっかりしていただいて、ぜひ全体にわかるように、私たちにもわかるようにぜひ広報していただきたい。丁寧にやっていただきたいと思います。\nあともう１つ、英検のことなのですが、ちょっとだけ具体的に聞きたいのは、英検は結構受けていらっしゃる方が多いのですが、６年生、小学校のところは全国では初めてではないかと、２００人を想定されているのですけれども、実際、中学生のところは中学校のところでやられていると思うのですが、小学校のこの２００人というのがどこで検定を受けるのかというのが１つと、英検の主体と学校とのかかわりがどういうふうになって行われているのかというのを具体的なところで教えてください。"},{"i":151,"speaker":"野呂瀬学務課長","text":"まず、６年生ですけれども、２００人と書いたのですけれども、実際、区立の学校で何人受けているかわかりません。品川区の中で、６年生が、昨年受けたのは１７８人と英検のほうに聞いております。ですから、これはもちろん私立の子もいるでしょうし、わからないです。今、区立の６年生は大体２,２００人ぐらいいるのですけれども、昨年受けた１８０人弱の中で、区立の子がどれぐらいいたかは把握していないですけれども、当然今回は区立の子だけという対象ですので、最大でも２００人ほど見込めばという形で算出をしております。\nそれと英検協会と主体ですけれども、今現在、中学校のほうは１５校ありまして、全部、準会場方式ということで、１０人以上集まれば、その学校が、準会場ということで試験会場になれるということで、今現在やっております。ですから、中学校のその会場に小学校のほうで希望者がいれば、近くの学校にお母さんなどに連れてきていただくということを想定しておりますけれども、今、具体的に、今回、秋に向かってどういう形でやるかというのは、これから各学校と詰めていくという状況でございます。"},{"i":152,"speaker":"飯沼委員","text":"その小学校のところなのですけれども、つかめていないという現状だと思うのですが、中学校の先生に言わせると、どこの学校かわからない子どもが結構中学校で受ける方のつながりで、書類をもらったりとかしながら、小学生が結構来ているのだそうです。でも、その子たちがわけがわからなくて、書き方から何から現場ですごく対応に苦慮しているという意見も聞いたので、ぜひその辺、新たに公費助成で行うというところにおいて、人数も多分増えるのではないかというのと、その辺は事前にしっかりと把握してやっていただきたいと思います。現場の負担が非常に、把握していない子どもたちのところが、とまどっても困りますので、丁寧にやっていただきたいと思います。"},{"i":153,"speaker":"鈴木（博）委員","text":"今、飯沼委員のほうから大分わからないような話が先走って進んでしまったので、もう一度、先ほどのオンラインのマンツーマン英会話レッスンについてお聞きしたいのですけれども、これを読んだときに、これは非常にいいなと思って質問しようとしたら半分ぐらいされてしまったのでかいつまんでしますけれども、まず第一に、これはさっきのお話だと学研からの持ち込みということだったのですけれども、相手の会話をする先生が、どういうレベルの人で、どこの国の外国人で、フィリピンでネイティブだと、タガログ語ですよね。ネイティブはちょっと違うと思う。話す時間が、どのぐらいがネイティブなスピーカーとの会話の時間なのか。要するに、直接向こうの人と話す時間はどのぐらいあるのかということをお聞きしたいのです。"},{"i":154,"speaker":"渋谷指導課長","text":"フィリピンの現地講師は、基本的にスービックというところと、セブと２地域の方を現地講師として予定をしているということでございます。実際、昨年度２月に学研の編集部の方が現地のほうに視察して、実際の英語能力等々については確認をされてきているということを聞いております。\n２５分間、最初に１０分ぐらい準備をして説明をして、中学校は５０分授業ですので、説明をして、その後、１０分たった段階から向こうと同じ画面がインターネットでつながりますので、２５分間、そういう意味では話しっ放しということになります。２５分やった後に接続を切って、１５分ぐらい今度は教室で復習をしたりだとかというような時間をして、１つの５０分のコマの中で実際やっていく、そんな進め方になっていると聞いています。"},{"i":155,"speaker":"鈴木（博）委員","text":"日本人が英語を話すときに、僕も外国へ行ってそうだったのですけれども、外国人と直接話をするというのは最初は非常に大変で、日本人は照れやが多いですから。だから、直接会話をするということに関しては、非常に意味があると思うのです。体験学習みたいなもので。しかも、それはやりとりで、こう言ったらこう返ってくる、わからないから応用していろいろ勉強になると思うのです。\n先ほどのお話だと、例えば受動態の授業のときに、その受動態に沿って会話をするとかというようなお話だったのですけれども、それだったら別に外国人と話などしなくても、日本でネイティブのインストラクターの人とか、英語の先生が話せば十分なことだから、わざわざオンラインで直接生の外国人と話をするせっかくの機会があるのだったら、もう少し発展的な、成果がどうのとか、子どもが個人差があるとか、話して楽しければそんなことは関係ないので、だから、実際、子どもたちが楽しくて、外国人と物おじしないで少しでも積極的にネイティブと話が、問いかけができるようになるような、そういう授業だったらいいのではないかと思ったのですけれども、その辺の企画などはいかがなのですか。"},{"i":156,"speaker":"渋谷指導課長","text":"まさに委員ご指摘のとおりで、子どもたちの能力差に応じるということは、全く固まってしまう子については「Repeat after me」からなのです。その段階でやって、実際にもっともっとコミュニケーションをとりたいという子は、「実は僕、趣味がこうなのだけれども、先生どうなの」と、それは自由にやりとりするという、その部分の発展形がいかようにもつくれるのがこのマンツーマンのまさに醍醐味であるし、そこが子どもの能力差に応じるというすばらしいいい体験になるのではないかと考えているところであります。"},{"i":157,"speaker":"高橋（し）委員","text":"ただいまオンラインの話が出たので、学力によるというところもあるのですけれども、やっぱり導入時にグローバル人材学習塾のときに、やや受講生とのコミュニケーション不足があったということがあったので、余計にこちらはマンツーマンなので、その点は今お話あったように十分研究してカリキュラム等もつくっていただきたいと思います。それは要望で。\n授業の時間なのですけれども、現地との関係とかで、何月の何時にという、第１、第３何曜日とか、もし結構限定されるとすると、進度の問題とか、学校のクラスの、このオンラインマンツーマンに拘束されて授業のほうがそれに合わせなければいけないとかというふうになっていかないように、ここまでいったからできるように、では、マンツーマンでいきましょうみたいな、そういう柔軟性がないと、何月何日は、この２校、全部が何時間目にやりますというのだと、先ほどちょっと現場のお話がありましたけれども、現場としてはやりにくいという中で、もちろん生徒にとってということがあるので、そこをどういうふうな、実施の日にちの決め方というか、そのあたり、これからなのでしょうけれども、カリキュラムのほうです。\nスマホのところは、この９００万円というのはアプリの導入で、ランニングというか、それも全部含めての話なのでしょうか。それとも来年度からランニングの面でまた契約してみたいな、ここの業者がそうなのか、そういうことも含めてもうこれでずっといけるのか、そういうことはまずないと思うのですけれども。"},{"i":158,"speaker":"渋谷指導課長","text":"基本的には、多分月に２回で、第１週、第３週の何曜日の何時間目が何年何組という決め方でコマを入れていくという形の運用の仕方になろうと思います。\nただ、カリキュラムについてはかなり弾力的に組めるというふうに聞いております。基本的に、今、例えば授業でレッスン９をやっていたら、オンラインでやるところはレッスン８までの、基本的に前にやったところの復習ベースで、その前にやったものをベースにしながら、それをネタにやりとりをするというふうな進め方になるので、あまり拘束されて学校がやりにくいということにはならないです。現場の先生と話をしている中に、ただでさえ教科書が終わらないのに、こんなものが入ったら教科書か終わらなくなってしまうのではないかみたいな、そんなご指摘もありました。したがいまして、授業でレッスン幾つでやったものを、例えばペアワークで子どもたちが対話をやっていたりだとかという部分をこのオンラインに置き換えるというようなことで、全体のカリキュラムの中で圧迫されるということがないようなカリキュラムの組み方をしていくところが１つのポイントになってくるところでございます。"},{"i":159,"speaker":"伊崎子ども育成課長","text":"子育てアプリのランニングコストでございます。今回、計上いたしましたのは、構築費でございますので、来年度以降の計上分については、今回の補正予算を可決いただいた後、来年度の予算で計上を考えているところでございます。"},{"i":160,"speaker":"高橋（し）委員","text":"ありがとうございます。\nオンラインのほうは、ある程度、何曜日何時というふうになってしまうのと、今、時間数の話で出たのですけれども、２５分とはいえ、１コマそこに費やすことになります。そうすると、週に１コマそこに入っていくと、今お話しあったように、年間でなかなか終わらせるのは厳しいというところなので、何らかのひずみが出てくるので、そこは検討して、年間で総合の時数になるわけですので、さっきの英検の受験ではないですけれども、そっちのほうにうまく力が向けられればいいですけれども、そういうこともあるので、カリキュラムの編集はちょっと検討していただきたいと思います。\nそれから、ランニングのほうは、幾らぐらいなのですか。ほかのところでやっているのを見てみますと、いろいろあるのでしょうけれども、予算の話なのであれですけれども、ほかの自治体は幾らぐらいなのでしょうか。"},{"i":161,"speaker":"伊崎子ども育成課長","text":"予算の話でございますので、まだはっきりとこちらのほうでの計画はこれからなのですが、世田谷区で似たようなことをやっていまして、そちらの経費は３８０万円ほどがランニング経費で、改善が必要な場合は別途コストがかかるというふうに聞いております。"},{"i":162,"speaker":"浅野委員","text":"重なる部分もあるのですけれども、最初に、医療的なケアを必要とする障害児に対する保育料助成についてですけれども、私もご相談を受けたことがありまして、なかなか品川区で対応できないという、そういう話も聞いております。その中で、今回は助成制度という形で、一歩前進かなというように思います。ただ、先ほど別の委員からもお話がありましたけれども、区内でぜひとも対応していただきたいと思います。２カ所、杉並区と横浜の話も出てきましたけれども、やはりそこに預けて、向こう方面だったらまだ可能性はあるのでしょうけれども、なかなか難しいと思います。そういう意味では、やはり区内で預けることができれば、そういう親御さんも喜んでいただけるのかなと思いますので、今後、検討していただければと思いますので、決意のほどをひとつお伺いしたいなと思います。\nそれとあと、オリンピック・パラリンピック関係で、教育推進校という話がありました。これは東京都の取り組みに、それに乗っかると言ったらおかしいですが、それを活用してということだと思いますけれども、平成２６年度はどうだったのかと思いつきまして、何校が指定されたのか。それと、今度、平成２７年度ですけれども、これからのことになるかと思うのですけれども、何校ぐらい指定をされるといいましょうか、指定を出していくのか、ここら辺のことについては細かいことは私もわかっていない部分があると思うのですけれども、各学校でそういう特色を持った形で、オリンピック・パラリンピックに触れていくという、そういう取り組みをしていただきたいと思いますので、その点お聞かせください。\nそれと、理科の観察実験支援事業ですけれども、これも理科離れというのが一頃、今もそうなのかちょっと私も認識はしておりませんけれども、言われてから久しいわけですけれども、これは取り組みとしては、理科の先生ですか、実験をする先生を導入するというのでしょうか、呼び寄せる費用なのか、それともまた別に何かプラスアルファで機材をそろえたりとか、そういうようなこともされるのかどうかということについて教えてください。\nオンラインの英語レッスンについては、今、他の委員からも質問ありましたとおり、ある意味では企業もやっている、そういうような中で、子どもたちにも適用して英会話に努めていただくということで、それはぜひとも大成功にしていただければなと思います。\nやはり英語に触れる機会が多いということが重要だと思うのです。私が小学校、中学校のときは、触れる機会は全くなかったということを今でも記憶していますし、それと今は時代が違うのだよと言われておるとおり、英語に力を入れて子どもたちを成長させていっていただきたいなと思いますので、この点は要望でございます。"},{"i":163,"speaker":"竹田保育課長","text":"まず、医療的ケアを必要とする障害児を区内の施設で受入れをというご質問でございますが、今までも区内の施設、通常の障害のある児童、あるいは同様の配慮をするお子さんについては、本人のプラスになるのであれば積極的に受け入れてきたところでございます。ただ、今回のようなかなり特殊といいますか、難しい問題をはらんでいるお子さんのケースについては、一定程度のノウハウも必要でございますし、需要等も考えながら、あるいは、お子さんの発達状況も見ながら受入れが可能かどうか検討していきたいと考えております。"},{"i":164,"speaker":"村尾教育総合支援センター長","text":"それでは、私から、オリンピック・パラリンピック教育推進についてお答えいたします。\n昨年度、平成２６年度は、５校指定をして実施をしております。そして本年度につきましては、小学校、中学校、一貫校も含めて全１１校でこの推進事業を実施しております。ただ、今回この補正につきましては、平成２７年度の当初予算では、５校分ということで予算計上を行っていたのですが、平成２７年度の４月に都のほうの通知で、拡大をするのでぜひもう少し手を挙げていただきたいというような通知がございましたので、改めて区のほうの学校に指定したところ、６校分プラスアルファでつけられたので、合計１１校ということで補正を組ませてもらっています。\nまさにこのオリンピック・パラリンピック教育推進ということで、各学校でさまざまな人材を呼んだり、また、各学校でオリンピックの歴史を学んだり、そういうような取り組みについては十分推進をしていきながら、また、いろいろな機会でその学校の取り組みを他校にも広げていければというふうに考えているところでございます。\n２点目、理科観察実験支援事業でございます。先ほど委員お話しいただいたとおりなのですが、小中学校においては理科の観察実験に使用する設備の準備等の補助員という形で、あくまでも教師が授業を行いますが、それの補助ということで人を学校のほうに、理科の授業に参加をさせて、より実験観察の質を上げていくというような、そういう取り組みでございます。"},{"i":165,"speaker":"浅野委員","text":"それぞれありがとうございました。\nまず、このオリンピック・パラリンピック教育推進校ですけれども、これまでですと、全部で１１校になるのですね。そのぐらいの数なのでしょうか。学校の数はまだ多いわけでありますので、なるべく１校が１回はそういう推進校になっていただいて、何らかの形で子どもたちが触れる機会、卒業してしまうとずれてしまうかもしれませんけれども、そのような努力もまたしていっていただきたいなと、そのように思います。\n理科のほうについても、補助員という形でアシスタントですか、そういう形で手助けをしてくれるということですので、こちらもぜひ継続した形で進めていっていただきたいと思います。\n最初の質問でありました医療的なケアにつきましては、重々承知の上でお願いをしておりますので、またそういう意味では、福祉的な部分ということになるかと思いますけれども、今後とも積極的にお願いいたします。"},{"i":166,"speaker":"大倉委員","text":"子育て支援情報発信アプリなのですが、世田谷区で先ほどやられているようなものと言っていたのですが、それでいいのか、同じような、似たようなものなのか、どういった内容のものを考えているかということを教えていただければと思います。\nまた、子育ては広いので、産まれた後からそういった発信をしていくのかとか、いつとか、時期、どの辺を想定しているのか教えていただきたいのと、あと、オンラインマンツーマン英語レッスン、モデル校の選定について、どうやって、ここの２校の理由を教えていただきたいと思います。これは本当に子どもたちが話す機会というのは非常に大事だと思いますし、まさにネイティブの方と英語を話しながら、話していく、伝えようとするという会話の仕方というのが、なかなか外国の方とする機会が少ないので、非常にいいことと思っておるのですが、今後、英語の授業として、これだけの成果があったとかという効果の測定の仕方、効果測定をどうやっていくのかと、あと、その後、タブレットを通してやった人たちが、今度、実際に外国の方と話すみたいなことも想定しているのかなと思ってはいるのですが、その辺、もしお考えがあれば教えていただきたいと思います。"},{"i":167,"speaker":"伊崎子ども育成課長","text":"子育てアプリの質問でございます。まず、世田谷区のほうで公開していますものが、誰でも今はダウンロードというか、アプリを無料で購入できるようになっていまして、ちょっとそれを拝見させてもらっております。見てみますと、子ども・子育ての年代に、住所地に応じて登録をすれば必要な情報が来るというものと、あとは、自分から必要なものを見に行けるというような、両方兼ねたものとなっているようです。当然、品川区で構築していくにあたりましては、そういった先行しているものを参考としながら、今実際に子育て情報誌という紙ベースの子育ての情報をお伝えするものについて、子育て世代の方を中心とする区民の方に意見を伺いながらやっておりますので、そういった方の意見を伺いながら、品川区の実情に合わせたプラスアルファを持ったものをつくっていきたいと考えております。\n対象としましては、妊娠期から就学前、学校入学前までのお子さんをお持ちの保護者の方と考えております。"},{"i":168,"speaker":"渋谷指導課長","text":"オンラインについてのご質問についてお答えいたします。\nまず１点目、モデル校選定の理由でございますが、浜川中学校、それから大崎中学校は、それぞれタブレットを導入している学校でございますので、そういった観点からまずこの２校で先行してと。実際、オンライン英会話そのものは、タブレットでなくてもパソコン教室でもできますので、ここの成果を見ながら展開を考えていきたいというふうに思っておるところでございます。\n２点目、効果測定でございますが、基本的には、先ほどから何回も出ています子どもが好きになるということが大事ですので、子どもへの意識調査のようなものがまずメーンになろうかと思います。それから、実際、英語能力がどうかということについては、昨年度から９年生を対象に、話す、聞く、読む、書くの４技能を調べるＧＴＥＣという総合的な調査をしておりますので、これの経年的なデータを見ていきたいというふうに考えているところでございます。\nそれから３点目、こういった学びをした子どもたちが外国人との交流をということでございますが、これも一昨年度から始めておりますグローバル人材育成塾、放課後の英会話教室に子どもたちが、そういったところに積極的に参加する子どもが増えればいいなということだったりとか、また、そこを対象にした子たちが、夏休みにイングリッシュ・キャンプというものもまた希望者を募っていきますので、そういったものに参加したりだとか、最終的には中学生の語学派遣研修などに参加する子どもたちが、こういったところからどんどん出てきてくれればというふうに考えているところでございます。"},{"i":169,"speaker":"大倉委員","text":"それぞれありがとうございました。\nアプリについても、ぜひ皆さんが使いやすいようにしていただきたい。区民の方々に伺うと言っていましたけれども、どういった方に伺うのかというところだけ教えていただければと思います。"},{"i":170,"speaker":"伊崎子ども育成課長","text":"今現在、子育てガイドの編集にＳＫＩＰという、ＮＰＯではないのですが、子育てをしているお母さんたちの団体と協働でやっております。そういった方を中心にお話をいただいていこうと考えています。"},{"i":171,"speaker":"伊藤副委員長","text":"１点だけお伺いさせてください。\n待機児童解消対策費について、この中で、都市公園の中の保育園の話がありました。非常に関心がありますので、プロポーザルされていたのですけれども、例えば、具体的にいつぐらいまでにその回答を求めていく、それからスケジュール、議会への報告等々についてはどうお考えなのでしょうかということだけお答えください。"},{"i":172,"speaker":"今井待機児童対策担当課長","text":"この事業につきましては、予算が成立後、一般競争入札で事業者のほうを、仕様を固めまして選定していきたいというふうに考えております。\nこちらのほう、スケジュール感覚につきましては、まずはどういうふうな調査項目を立てるかにつきまして、公園課と協議しながら、秋ごろまでには調査項目の確定をしていきたいというふうに思っております。\n理由は、二、三カ月に１回、国家戦略特区会議がございまして、東京圏の会議が、前回、６月の下旬に開催されました。これが二、三カ月に１回と聞いておりますので、先ほど申しました施設基準の詳細、緩和策が出てくるのが９月の下旬というふうに聞いておりますので、やはりそこを踏まえませんと、具体的な公園等の調査は難しいかというふうに考えております。"},{"i":173,"speaker":"伊藤副委員長","text":"まとめますけれども、このことについては、多分全ての会派の方々がこれにすごく関心を持っていると思うのです。なので、今、国の方向性もしっかりととらまえた上で、なるべく早く議会に報告していただきますようお願いしておきますので、よろしくお願いいたします。"},{"i":174,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来。"},{"i":175,"speaker":"鈴木（博）委員","text":"賛成か反対か。"},{"i":176,"speaker":"塚本委員長","text":"そうですね。"},{"i":177,"speaker":"鈴木（博）委員","text":"賛成です。"},{"i":178,"speaker":"浅野委員","text":"賛成です。"},{"i":179,"speaker":"石田（ち）委員","text":"賛成です。\nそれで一言。医療的なケアの必要な子どもへの施設、本当に品川区内でつくっていただきたいということを最後に強く要望したいと思います。"},{"i":180,"speaker":"大倉委員","text":"賛成です。"},{"i":181,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":182,"speaker":"塚本委員長","text":"それでは、これより、第５５号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）について採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":183,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n以上で議案審査を終了いたします。\n会議の運営上、暫時休憩いたします。\n○午後 ０時２８分休憩\n○午後 １時３０分再開"},{"i":184,"speaker":"塚本委員長","text":"ただいまから、文教委員会を再開いたします。\nなお、ただいま１名の傍聴申請がございますので、ご案内をいたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n平成２７年請願第１８号 子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願"},{"i":185,"speaker":"塚本委員長","text":"それでは、予定表２、請願・陳情審査を行います。\n平成２７年請願第１８号、子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願を議題に供します。\n本件は、初めて取り上げますので、書記に朗読させます。\n〔書記朗読〕"},{"i":186,"speaker":"塚本委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者の説明を求めます。"},{"i":187,"speaker":"今井待機児童対策担当課長","text":"それでは、私から、本請願の項目についてご説明いたします。\n請願項目の１点目についてでございますが、区では高まる保育需要に対しまして、平成２２年４月１日から平成２７年、今年度の４月１日までに、３,３５２人の受入れ枠の拡大を実現してまいりました。さらに年度内には、この７月に認可保育園を２園、それから１２月にはさらに１園を開設するなど、受入れ拡大を図る予定です。\n今後も認可保育園、小規模保育などの地域型保育、認証保育所の開設等により、総合的に取り組み、区の政策目標の１つであります待機児童ゼロを目指し、引き続き、総合的な待機児童対策を進めてまいります。\nまた、平成２８年度につきましては、認可保育園、認証保育所の新規開設に加え、広町二丁目の大規模保育施設の開設により、保育の受入れ枠を現在のところ、６２０人の予定で拡大する予定でございます。\nさらに、今後の動向を踏まえ、さらなる認可保育園や小規模保育事業の開設を検討してまいります。\n請願項目の２点目についてでございますが、屋外遊戯場、いわゆる園庭につきましては、保育園の屋外遊戯場、そしてその代替地となる公園や広場等につきましては、児童福祉施設の整備および運営に関する基準や通知によりまして設置しております。これら公園、代替地も含めまして、公園を活用して、保育所保育指針にのっとった十分な保育が可能と考えております。\n請願項目の３点目についてでございますが、現在、品川区には区立公園として公園等が１４７カ所、児童遊園が６７カ所のほか、防災広場など、合わせて２６３カ所ございます。公園は小さな子どものほか、高齢者を含めさまざまな世代や目的を持った方が集う公共のスペースでございますので、引き続き、幅広い需要を踏まえて整備を進めているところでございます。"},{"i":188,"speaker":"塚本委員長","text":"説明が終わりました。\nこれより質疑を行います。ご発言願います。"},{"i":189,"speaker":"飯沼委員","text":"まず初めになのですけれども、本日の請願は、認可保育園の大幅増設を求める請願なのですが、このところ毎年、毎議会ごとにこの認可保育園増設を求める請願が出されているわけですけれども、このことに対して、区としてどう受けとめていらっしゃるのかということをまず最初に１点お伺いしたいのと、あと、改めて数字をお伺いしたいのが、今年度の４月１日のところで、認可保育園を希望した人数、入園できた人数、不承諾だった人数、あと、区が待機児と数えている人数をそれぞれ教えてください。"},{"i":190,"speaker":"今井待機児童対策担当課長","text":"初めに、定例会ごとに子育ての方から認可保育園の開設についてのご請願をいただいていることにつきましては、やはり待機児童解消ゼロを求める皆さんの区民の声だというふうに認識しております。その政策目標を実現するために、区としても総合的に待機児童対策に取り組んでいるところでございます。\n次に、平成２７年４月１日の数字でございますけれども、申込者数につきましては２,７９９人、新規入園された方については１,７８４人、いわゆる利用不可、不承諾と申しておりますが、利用不可の方は１,０１５人でございます。国の定義に基づきまして算出いたしました待機児童数が２１５人でございます。"},{"i":191,"speaker":"飯沼委員","text":"今出していただいた数字なのですけれども、いわゆる不承諾が、区が算定をする待機児が２１５人ということなのですけれども、この差について、厚生労働省の内容に基づいて算出をしているということなのですけれども、１,０１５人から２１５人に至る引かれた部分、どういう理由で引かれているのかということを改めてお聞きしたいと思います。\nあと、認可保育園の受け皿なのですが、このところ、平成２７年度、平成２８年度、プレス発表でも数字が出ていますが、改めて平成２７年度の認可保育園の受け皿の数と、そのうちの０歳から２歳の受け皿が何人あるのか、平成２７年度と平成２８年度と、それぞれ教えてください。"},{"i":192,"speaker":"今井待機児童対策担当課長","text":"初めに、厚生労働省の今年の調査の経緯でございますが、いわゆる休職中を含め、認証保育所、幼稚園、認定こども園等に入っていらっしゃる方、それから一定の期間を過ぎても申込みがなかった方を含めまして２１５人ということになっております。\nそれから、平成２７年の認可保育園の受入れの拡大でございますけれども、すみません、ちょっとお時間をいただけますか。\n平成２７年度７０９人の受入れ拡大のうち、認可保育園で開設する部分は、今、４８８人を想定しております。０歳から２歳については、今、手元にすぐ資料はございません。"},{"i":193,"speaker":"塚本委員長","text":"平成２８年度は出ますか。認可保育園の受入れ枠の計画。"},{"i":194,"speaker":"今井待機児童対策担当課長","text":"失礼いたしました。平成２８年度につきましては、７０名定員の認可保育園を４園ですので２８０人、それと、大規模保育施設が定員３００人ですので、６２０人のうち５８０人が認可保育園ということで予定しております。"},{"i":195,"speaker":"飯沼委員","text":"ありがとうございます。\n今お伺いした平成２７年度と平成２８年度のところの受入れ枠、認可保育園に関してお伺いしたので、７０９人と５８０人、合わせると１,２８９人なのですね。０歳から２歳はちょっと数字がわからないということなのですけれども、おおよそ半分ぐらいと考えてもよろしいのでしょうか。０歳から５歳の間で、０歳、１歳、２歳が約半分ぐらいかなと思うのですけれども、その辺の考え方についていかがでしょうか。"},{"i":196,"speaker":"今井待機児童対策担当課長","text":"申しわけありません。平成２７年度は、総受入れ枠が７０９人で、その中で平成２７年度があきますのが、今、すみません、私のほうで数を間違えてお話ししたかもしれませんが、４８８人です。先ほど５８８と申し上げたかもしれないです、４８８人です。\n０歳から２歳につきましては、委員ご指摘のとおり、半数以下の状況になっております。"},{"i":197,"speaker":"飯沼委員","text":"今の数字だと、４８８人と５８０人で１,０６８人、半数以下ということは、約５００人くらい。平成２７年度と平成２８年度と合わせて、最も保育を必要とされている０歳、１歳、２歳のところが、約５００人くらいの受け皿だという受けとめをいたしました。\nあと、この中にも書いてありますが、３歳になったら受け皿がなくなっていく。認証保育園、中には５歳までのところもわずかにありますけれども、ほとんどが０歳、１歳、２歳ということで、認証保育園、あと、ここのところ区が進めています小規模の保育事業、あと、その他の認可外の保育園がありますけれども、この辺のお子さんの数を教えていただきたいのが１つです。\nあと、母親の希望として、今回の請願も中心的なところは認可保育園の大幅増設というところを願っているわけですけれども、ママやパパたちは、とにかく認可保育園をつくってほしいと言って頑張って、結局は入れなかったというところにおいて、認証に行ったり、小規模保育事業に行ったり、認可外に行ったり、あと預けることができなくて職を辞めたり、いろいろなケースがあると思うのですが、それぞれの立場の中で、やっぱり受け皿、一応受け皿になっているところに入っていても、認可保育園に入りたいのだ、ぜひ認可に入れてほしいというところでこういう請願が出てきていると思うのですけれども、この希望するところ、今回の請願のいろいろなところに入っていらっしゃるけれども、そうではなくて認可に入りたいのだという切実な願いに対して、区としてどう責任を負って具体的に受け皿をつくっていくのかというところを改めてお伺いします。"},{"i":198,"speaker":"今井待機児童対策担当課長","text":"最初のご質問は、３歳児の受け皿というご質問というふうに理解したのですけれども……。"},{"i":199,"speaker":"飯沼委員","text":"そうです。受け皿としながら、認証保育園に入っているお子さん、小規模保育事業に入っているお子さん、あと認可外に入っているお子さん、その人数を教えてください。"},{"i":200,"speaker":"今井待機児童対策担当課長","text":"事務事業概要のベースで申し上げますと、地域型保育につきましては、現在、２歳児でご利用の方が５５名という、そういう形でよろしいでしょうか。２歳児でお通いの方が在園児が今、５５名いらっしゃいます。それから、認証保育所ですが、事務事業概要の８６ページにはなりますけれども、地域型保育、小規模保育など、０歳から２歳の家庭的保育および小規模保育に入っている２歳児のお子さん……。〔「２歳児ではなくて、トータルの人数をまず知りたいのです」と呼ぶ者あり〕定員ベースにつきましては、地域型保育事業につきましては、現在、２３４名の地域型保育の定員ベースを持っております。それから、認証保育所につきましては８０４名でございます。\nそれから、認可保育園のご希望でございますけれども、希望するところというふうなご指摘がございましたけれども、やはりご希望はさまざまでございますので、中には地域型を優先的にお選びになる方も若干ではいらっしゃいますし、認証を選んでいる方もいるというふうにも聞いております。\nただし、品川区としましては、認可保育園に入りいたいというふうなご希望を受けまして、なるべく窓口で丁寧にご説明を、近隣の認可保育園だけではなく、地域型保育、そして認証保育の場所等についても丁寧にご説明申し上げ、マッチングを図っているところでございます。"},{"i":201,"speaker":"飯沼委員","text":"いろいろなところでマッチングを図っている。とにかくどこかに入れないと仕事が続けられないので、いろいろな施設が今あって、その紹介をしているというところは大事であると思っていますけれども、やはり大もとのところにおいては、認可保育園を希望している人たちが、今出された数字の中にいらっしゃるということと、あと、３歳になったら受け皿をなくしていってしまうような、地域型、認証のところでも、今ご紹介あった中でも１,０００人以上いらっしゃいますね。あと区がどれだけつかんでいるかわかりません。認可外のところにもいらっしゃる方がおられるというところにおいては、今の品川区が進めているテンポ、平成２７年度、平成２８年度のところも約５００人ぐらいなので、圧倒的に足りないという認識を私たちは持っていて、毎年毎年待機児がここのところ膨らんでいるという実態から見ても明らかだと思うので、やはり今のテンポでは足りない、そのところで改めて具体的にどう受け皿をつくっていくのかという質問をしたつもりなのですけれども、この点はいかがでしょうか。"},{"i":202,"speaker":"今井待機児童対策担当課長","text":"今、委員ご質問の定員ベースですと、それは０歳、１歳、２歳合わせてでございますので、２歳児、地域型で言えば２歳児の定員枠は５５名という形に、在園児はおります。また、中には地域型、認証保育で認可保育園を同時に希望されて、認可保育園に入りたいというご希望の方もいらっしゃるということはつかんでいるところでございます。\nテンポまたはペースのことでございますけれども、今回も私ども、待機児童の状況を踏まえまして、５月の臨時会で大規模保育施設の提案をさせていただきましたけれども、今後、人口動態の調査等も出ますので、子ども・子育て計画にのっとって今進めているところでございますが、さらに人口動態の調査等を踏まえて、これは改めて見直しする必要があれば見直しをしていくというふうな考えでおります。"},{"i":203,"speaker":"飯沼委員","text":"ありがとうございます。\n私は今日の請願のママやパパたちの意見を受けとめて、私も地域でも子育ての相談はかなり受けているので、本当にかつてない深刻な事態、子どもたちは日々成長をしているので、１年、２年、３年先などと言ったら追いつかないのです。今の子どもたちの成長をどう支えていくのかというところでは、本当に一刻も早くというか、直ちにこの問題を解決していかなくてはいけないと受けとめています。私は今いろいろ数字をお伺いしましたけれども、こういった事態を捉えられて、今日、委員の方、各会派の皆さん、多分実態を受けとめておられると思うので、その辺をどのように受けとめていらっしゃるのか、また、この足りない保育園をどう解決していったらいいのかとお考えがありましたら、ぜひ聞かせていただきたいと思いますが、いかがでしょうか。"},{"i":204,"speaker":"浅野委員","text":"待機児童対策ということで、確かに認可保育園ということで、入りたいという方は多いかと思います。また、区のほうでは、認証保育所とか、さまざまな形態で受入れ枠等を拡大しつつ進めてきているということですが、今後、品川区の人口動態を調査されるとは聞いておりますけれども、そういうことに照らし合わせると、どのようなカーブと言ったら怒られてしまうのでしょうけれども、今後の見通し、保育園に入りたいという方の見通しというのはどのように考えておられるのか、その点について教えてください。"},{"i":205,"speaker":"今井待機児童対策担当課長","text":"事務事業概要でも乳幼児人口の推移をお示ししておりますけれども、一定、１月１日の時点では０歳児が去年よりも下がった中で、４月１日になると今度は上がっていくという中では、やはり保育園も含めて、就学前のご希望というのは大変大きいものが、小学生施設に対するご希望が大きいものというふうに考えております。やはり出生の０歳の動向というのがなかなか捉えにくいというのは、この間、区でも答弁しておりますけれども、０歳人口がまだピークを迎えているという状況ではございませんので、今後、引き続き数年間、０歳、１歳、２歳の一番高いピークのところというのは、高どまりが続いていくというふうに考えております。\n一方では、やはり女性の出産人口が実際には減っていく状況もございますので、今後、社会的な動向と自然的な人口の動向、両方を加味した中で進めていきたいというふうに考えております。\nまた、一番端的に数字がとれますのは、入園の申込者数、これがどのくらい伸びていくかというところがございますので、人口だけではなく、この入園の申込みの割合、これを見ながら整備を進めていきたいというふうに考えております。"},{"i":206,"speaker":"浅野委員","text":"品川区は人口が増加をしているということもありまして、それはまた区からすればいい傾向だとは思うのですけれども、待機児童が増えてしまうと、やはり入れないという方は厳しいのかなというふうに思います。\nその上で、前にも決算で発言させていただきましたけれども、待機児童の偏在というのでしょうか、荏原についてやはり厳しいという話を伺っております。そういう観点も含めて、やはり区が実施している総合的な待機児童対策、さまざまな観点から、ある意味では理解できるような内容で進めていっていただきたいなと思っております。特に荏原の地域につきましては、そういう状況、多分、議員の皆さんもそう思われているところもあるかと思いますけれども、なかなかそういった意味では難しいことはこちらも重々承知をしておりますけれども、さまざまな観点から過不足なくという言い方はおかしいのでしょうけれども、検討して進めていっていただければと思います。"},{"i":207,"speaker":"鈴木（博）委員","text":"１つだけ気になることをお聞きしたいのですけれども、待機児童の子どもの数がいろいろと計算されて出されているみたいなのですが、私が今、実際に小児科で開業していて最近すごく感じるのですけれども、外国人が認可保育園にすごく多い、中国人が多いのです。かなりたくさんいらっしゃるのですけれども、例えば、外国人、中国人などは、今の区の待機児童の予測の数の中に入ってきて、今後ますます増えていきそうな感じがするのですけれども、高どまりしてというそのパラメータの中に入って、当然それも加えた上で計算とか推定とか、外国からいらっしゃる方もたくさんいると思いますけれども、これが入っているかどうかお聞きしたいです。"},{"i":208,"speaker":"今井待機児童対策担当課長","text":"青少年人口の推移でもございますけれども、平成２５年１月１日からにつきましては、平成２４年に住民基本台帳法の変更がございましたので、外国人の人口も反映して行っております。\nまた、子ども・子育て計画の中で人口の動態をとるときに、基本は区の全体の人口動態の数値をいただきましたけれども、その時点での外国人の割合を含めまして、外国人も含めた形でのニーズという形で人口を捉え直しておりますので、現在の子ども・子育て会議では外国人も含んだニーズという形になっております。"},{"i":209,"speaker":"鈴木（博）委員","text":"一応、今現在、外国から来た方も統計の中に含まれているということで、それは理解したのですけれども、ただ、日本人の出産人口の経過と、外国から日本にいらっしゃってこちらで生活、流入してくる方というのは、必ずしもパラレルではないのではないかという気もするのです。その辺の配慮とか、計算とかもされたほうがいいのではないか。当然されているわけですよね。"},{"i":210,"speaker":"今井待機児童対策担当課長","text":"外国人の方の動向につきましては、やはり３・１１があったときに大分減ったという状況がありまして、私どもも窓口等でお伺いするのは、子どもを連れてこられていた方が子どもは本国に戻すような形もなさったというふうには聞いております。ですので、外国人の動向を含めまして、今ご指摘ございましたけれども、日本人の増加の指数だけではなくて、外国人のところに着目した指数もあわせて今後人口動態を捉えていきたいというふうに考えております。"},{"i":211,"speaker":"石田（ち）委員","text":"この請願の中に園庭のことも入っていますけれども、園庭がないために区内の公園がいっぱいになって公園渋滞が起きているということを以前に言わせていただいたのですけれども、私も地図に落として、公園が入っている地図と保育園の地図をいろいろ見てみて、専門的に半径何ｍ以内に何人というふうな表現はできないのですけれども、やっぱり公園が、保育園が多数あるところに比べて公園数は少ないなというふうに感じます。\nそれで、先ほど、公園や広場は基準によって設定されているというお話もありましたけれども、１つの公園の周りに複数の保育園があれば、それぞれの保育園にとっての基準の公園や広場になってくるわけですので、当然そこに近隣の保育園からお子さんたちが遊びに来る状況になるので、やはり公園渋滞が起きてくるのはとても当然なことなのですけれども、やはり公園を増設していくというところも３番目の請願項目に入っていますけれども、園庭とともに公園もというところは、今、区はどのように考えていらっしゃるのでしょうか。\nそれで、先ほども補正のところでありましたけれども、９０人規模の１,０００m2という、そういうのは園庭も加味した上で探していくのかを伺いたいと思います。"},{"i":212,"speaker":"今井待機児童対策担当課長","text":"初めに、屋外遊戯場の件でございますけれども、特に何ｍ範囲にどのくらい、どの程度の必要があるというふうな特定された内容ではございません。やはり２歳以上のお子さんが安全に歩いて行けるというところがポイントかと思います。\nまた、屋外遊戯場の件につきましては、それぞれの保育園の実施によりまして、たとえ１つの屋外遊戯場を規定していても、複数の園にどういう子どもたちが、逆に言うと、飽きないように遊びに行っているのが実態ですので、特定の公園に集中しているということは、私どもはそのようには考えておりません。\nそれから、大規模保育施設につきましては、敷地内に一定の中庭を設けるというふうなご説明をしたところでございますが、しながわ中央公園を代替地としておりますし、また、今度の公園における保育園整備に関しましては、こちらはもう隣接の公園自体を屋外遊戯場と捉えて施設整備を進めていく考えでおります。"},{"i":213,"speaker":"石田（ち）委員","text":"やっぱり子どもたちにとって、育っていく中で、広いところで遊び回るというのは大事なことだと思うのですけれども、私も友人の子どもたちと一緒に遊んだりする中で、ちょっと広い場所があるとすぐ走り出す。「危ないよ」と言っても、お母さんたちに伺うと、やっぱりうちも狭いし、保育園も園庭がないから、こういうところに来ると走りたくなるのだろうねという感想というか、思いが寄せられるのです。そういう中でも、やっぱり狭い中で、走り回れる場もない中で、そして公園に行ってもほかの園児たちもいるという状況では、本当に子どもたちの生き生きとのびのびとした保育というのはなかなか難しくなってくるのではないかと思うのですけれども。\nそれで、３００人規模の保育園ができれば、そこからまた大井町近辺の公園に３００人近くの子どもたちが遊びに来たりするわけですね。そうすると、本当に大井町近辺だけで見ても、公園はとても多いとは言えないので、これが本当にどうなっていってしまうのかと思うのです。\nなので、ぜひ園庭と、そして公園の確保、各保育園は本当に苦労していろいろやられていると思うのですけれども、東大井にある保育園から大井町駅を通って、さらにイトーヨーカドーのほうまで行ってという、公園に向かって歩く子どもたちを見ていますと、本当に保育士の皆さんもご苦労があるなというふうに思うのですけれども、それをやっぱり近くに、本当は身近にあれば、どれだけ安心で、どれだけ子どもたちも遊べるかなと思うと、やっぱりここはこれからつくる認可保育園には園庭を必ず設置し、そして園庭がどうしてもつくれないところであれば、近くに公園を設けていくということを進めていっていただきたいと思うのですけれども、いかがでしょうか。"},{"i":214,"speaker":"今井待機児童対策担当課長","text":"初めに、今、この都市部におきまして、敷地というのは大変、保育園の開設自体が困難なぐらいのところでございます。公園が果たしている役割は委員のほうで環境教育といいますか、環境の部分、一緒に体を動かす部分というところも強調されておられましたけれども、やはり公園で社会性を育むこともできるのではないかというふうに思っていますし、そういうものも指導していく内容だというふうに思っております。\n私どもの考え方では、敷地内の屋外遊戯場は必置ではございませんので、近隣の公園等を代替にして、そこで十分保育活動をしていただけるよう、今後とも保育園と協議して進めてまいりたいというふうに考えておりますので、屋外遊戯場を認可保育園の必置条件とする考え方はございません。"},{"i":215,"speaker":"飯沼委員","text":"この間、品川区は、認可を含めてさまざまな施策でやってこられた努力は認めております。でも、その努力が実態に合っているかどうか。私はそこが大事であると思っています。実態をつかむという努力も多分されていると思うのですが、お隣の港区では、人口増のところを人口動態の変化よりも実際的にマンションとかいっぱい建設をされているので、人口増のところをプラスアルファで上乗せをして考えているというところと、あと、地域ごとにどの年齢がどれだけ少ないのか、ただ人数だけではなくて、地域ごとにしっかりとつかんでいる。それも特別なアンケートとかをとったのではなくて、入園申請の申込みの用紙の中からそれを抽出して、地域ごと、年齢別の足りないところを出している。そういったことでは、保育園はいろいろな年齢をつくるので、ある地域では年齢がオーバーしてしまうところもあるけれども、０歳が足りない、１歳が足りないというところでは、新たな保育園をつくっていく。そういう手法でやっているということを聞いたので、ぜひ品川区も実態をきちんと把握を、まずされているのかどうかというところと、私は、いつもしつこく０歳は、１歳は、２歳はと聞いているところは、やはり足りないところに手立てをしっかりと立てていくということが大事なので、ぜひその努力をしていただきたいのと、実際にどこまでそういうことをされているのかということを最後にお伺いしたいと思います。"},{"i":216,"speaker":"今井待機児童対策担当課長","text":"初めに、地域別の件でございますけれども、品川区も入園の申込み状況に応じまして待機児童の確認をしております。\nやはり荏原地域では施設整備のほうはなかなか大きい場所が見つからないことから進んでいない。また、０歳、１歳、２歳のところで、特に１歳児は今回１２５人ということで待機児童を出しましたので、品川区としましては、０歳、１歳、２歳に効き目のある小規模保育、効果的に開設できる小規模保育も組み合わせて、認証保育所も組み合わせて、これは開設していかないと、総合的に組み合わせていかないと、なかなか皆さんの需要を満たすことができないというふうに考えております。\n引き続き、今、委員からご指摘ありました待機児童の多いこの０歳、１歳、２歳を中心に開設を進めているところでございます。"},{"i":217,"speaker":"飯沼委員","text":"どうしても認証とか小規模とか、いろいろ組み合わせてやっていきますという答弁に終わってしまうのですが、やはりそれの繰り返し、いくら実態をつかんでも、それの繰り返しが毎年毎年入れないお子さんを増やしてしまうというところにおいては、やはり認可保育園。認可保育園も特に品川区は来年３００人の区立の保育園を開設するというところに、私は新たな決断だと思っているのです。幼保一体化はあったけれども、認可保育園を新たに区でつくっていくという、やはりここのところに核心を持って進めていただきたいと強く思うわけですけれども、最後です、いかがでしょうか。"},{"i":218,"speaker":"今井待機児童対策担当課長","text":"先ほども平成２８年度の開設の中で、現在、６２０人の受入れ拡大のうち、認可保育園は５８０人ということでご説明いたしました。認可保育園はやはり数としては大変大きな柱になるものでございますので、認可保育園を一定柱にしながら、といっても、やはり小規模の０歳、１歳、２歳のところ、認証のところも組み合わせながら開設していくという方針に変わりはございません。"},{"i":219,"speaker":"伊藤副委員長","text":"いろいろ勉強させていただく中で何点か確認させてください。\n事務事業概要によれば、平成２７年度予算は、保育園関係に１００億円前後の品川区の税金が投入されています。予算ベース。たしか平成２７年度の区民税が３９５億円前後だったような気がするのですけれども、その中の１１０億円が保育園関係に投入されていることからすると、品川区は非常に子育て、保育園関係に重要な費用を払っていると聞くのですけれども、ざっくりな聞き方で申しわけないけれども、１１０億円前後の品川区の税金を投入することについて、まずは品川区の考え方をお聞かせください。"},{"i":220,"speaker":"今井待機児童対策担当課長","text":"この１１０億円は、開設の経費は例年、今年も５億円余ぐらいの認可保育園の開設経費をつけていただいておりますが、基本的には運営費等を含めまして、子育て施策全般のところがありまして、保育課でもやはり生活支援型のオアシスルームですとか、そういうものもやっておりますので、在宅子育ての方の一時預かりも含めて、幅広い形での１１０億円というふうにご理解いただければと思います。"},{"i":221,"speaker":"伊藤副委員長","text":"そういう意味では、非常に子育てについて品川区は対処しているところはすばらしいと思います。\n利用者の負担率を見ると１４.９％、つまり、全体の運営費の８割以上が税金でまかなわれている現状もその一方である。こういう請願・陳情は、なぜか公立保育園をつくるという請願があるのだけれども、例えば在宅の子育てをしている方々からの請願・陳情はほとんどないし、そういう方々がこういう現状を知ったら、極端なことを言うと、例えば、年間１５万７,０００円ですか、平成２７年の予算ベースで。これだけのことを品川区が子どもたちに投入するのであれば、在宅で子育てする方々についてもやっぱり何らかの影響が出てくる可能性があるわけなのです。ところが、なぜか毎回毎回、公立保育園だけをつくれという請願なので、どうしても不思議な感じがするのだけれども、それは置いておいて、私が指摘をしたいのは、区民税からこれら全てを運営していくのであれば、バランスをとった子育て施策を展開していく必要がある。つまり、在宅でも、それから私立の保育園、幼稚園に通わせている子どもたちに対しても、そういうさまざまな形で子どもたちの育ちをバックアップしていくことこそが品川区の区政だと思うのだけれども、そのことについてのお考えを改めてお聞かせください。"},{"i":222,"speaker":"金子子ども未来部長","text":"保育園等乳幼児に関する施策についての基本的なお尋ねですので私のほうからお答えさせていただきますが、現況、やはり保育園の申込み、非常に多いです。これに対して応えていくのは、私ども行政の責務だとは思っています。いつもお答えしているとおりなのですが、こういう箱物をつくっていくには、やはり中身の保育の充実も一方で図っていかなければいけない。ですので、これについてはソフトとハードと両面で考えていく。\nそれともう一方考えなければいけないのは、今、委員お話のありましたとおり、在宅で子育てされている方、こちらに対しても子育て支援、なかなか少子化社会、子育てに孤立感、あるいは不安感を抱えている方が非常に増えているという中では、在宅で子育てされている方への支援、サポートというのも一方で充実していかなければならないというふうに思っています。\nそういう意味で、私ども子ども未来部はこの両方を所管しておりますので、委員お話のとおり、これらの施策についてはバランスをとって考えていかなければならないと思いますし、また、区全体として、当然、全体を見て判断する者がおりますので、それについては全体で判断していくと、こういうふうなシステムで施策のほうも展開しているというふうに考えてございます。"},{"i":223,"speaker":"伊藤副委員長","text":"バランスというお話をされました。これからはそれが非常に大切になってくると私たちは思っています。\n先ほど、幼稚園のことをお話ししましたけれども、これから高齢化社会がさらに進んでいくわけであって、社会保障制度を中心として、税金の支出はおそらく増えていく。だけれども、だからといって増税するわけにはいかないわけであって、そうなると、今までのさまざまな政策の見つめ直しをしていく必要が当然出てくる。この中で保育園についても、約１００億円前後の品川区の予算が投入されています。これで保護者負担が１０何％、基準のことも考えていかなければいけない。やっぱりそれはどこかの時点でバランスということを考えていく必要があるということも指摘をさせていただくのと、それから、何も公立保育園だけに特化した施策ではなくて、例えば私立の保育園を導入する施策や、それから、民間事業者、それからさっき話があった国家戦略特区の進展によれば、もしかしたら公園の中に新たな保育園ができるかもしれない。要は、そういうさまざまな観点で待機児童対策をとっていくことのほうが、私は税制も、それから税金の使い方についても、ある程度、重要な担保をとった上で、でも、現実の維持に対処できると思うのだけれども、改めて品川区のお考えをお聞かせください。"},{"i":224,"speaker":"金子子ども未来部長","text":"さまざま大きい視点からご指摘をいただきました点も、先ほど来出ている広町の大規模保育施設です。これについては、私どものこれまでの基本的な考え方から言えば、民立民営にするのが本来ならベストだというふうに思っております。当然、民立民営ならば運営費についても国、都からの支出というものがあります。ところが、区立になると、こういうものも入ってきません。大井町の広町二丁目の大規模保育施設の特性というのは、ご案内のとおりですけれども、再開発の種地でありますので、これが５年後を一応目安としておりますが、いずれこれは再開発のほうに移行していかなければならないということがありますので、そういう意味では、民立民営ではかなり運営が厳しいだろう、運営事業者を募ったところで手が挙がらない恐れもあるというところから、こちらは公立民営というふうな手法を選択させていただいております。\nそういう意味では、私どもとしましては、保育園の運営に関しましては、やはり全体的な財政というものも考えながら、どういった手法をとっていくのが効率的な運営、あるいは保育の中身も含めてですけれども、どういった運営がいいのか、どういった運営に対して区として指導なり、サポートなり、助成なり、どういった手法をとっていけばいいのかというところはさまざまな研究をしながら、いろいろなシチュエーションを考えて結論を出していくべきだろうと思っています。\n今後ともさまざまいろいろな用地が出てくる可能性があると思っています。公園もその１つですけれども、そういった１つ１つについて最も効率がよい、あるいは質的にもこれのほうがよいというようなところを、各場面場面で検討して最善の答えを求めながら結論を出していく、こういう姿勢にかわりはないところでございます。"},{"i":225,"speaker":"伊藤副委員長","text":"決して私たちは待機児童対策をやらないということを言っているわけではなくて、進めていくべきだと思っています。だけれども、その手法において、全てが公立保育園だけではなくて、さまざまな主体を展開しながら、費用対効果も十分勘案しながら対処していく以外ないということの指摘をさせていただいておりますので、まさに今、部長がおっしゃったような方針で進めていっていただきますようお願いしておきます。よろしくお願いします。"},{"i":226,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、質疑を終了といたします。\nそれでは、平成２７年請願第１８号、子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願について、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらか、まず各会派にお伺いいたします。\n初めに、自民党・子ども未来からご発言願います。"},{"i":227,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":228,"speaker":"浅野委員","text":"結論を出す。"},{"i":229,"speaker":"飯沼委員","text":"結論を出していただきます。"},{"i":230,"speaker":"大倉委員","text":"結論を出します。"},{"i":231,"speaker":"高橋（し）委員","text":"結論を出します。"},{"i":232,"speaker":"塚本委員長","text":"それでは、本件につきましては、結論を出すでご意見がまとまったようですので、そのような取り扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":233,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すに決定いたしました。\n採決に入ります前に、本件につきまして、各会派の態度を確認いたします。\n初めに、自民党・子ども未来からお願いいたします。"},{"i":234,"speaker":"鈴木（博）委員","text":"保育園が足りないということは非常に緊必な課題でありまして、このような声が出るということはある程度理解できることですが、今、区のほうも精力的に待機児童対策を推し進めておりますので、区の今の取り組みを非常に高く評価しまして、このままぜひ続けていただきたいと思います。\n特にいろいろな、先ほど、伊藤副委員長からもあったように、子育てというのはいろいろなことをやらなければいけないので、その１つに特化してこれだけという形で限定するというところでは逆に区の待機児童対策に縛りをきかせるようなこともあるのではないかというようなことも考えまして、不採択。"},{"i":235,"speaker":"浅野委員","text":"さまざまな施策で総合的に待機児童対策をしていく、これまで区が進めてきて、また、これからも進めていくという、そのような流れかと思います。時により人口の動態も随分変わってくる。また、変わってくるという将来予測も出てくるかと思います。そういうときに変化に対応できるようなこともこれから考えていただきながら、認可保育園だけでなくして、総合的に最善な保育園の整備を進めていっていただければと思います。\nそういう意味からして、願意に沿いがたいということです。"},{"i":236,"speaker":"飯沼委員","text":"意見をつけて採択を主張いたします。\n本請願は、認可保育園の増設を求めているわけです。子どもは社会の宝物とか、社会全体で子育てを応援しようとよく言われていますけれども、人を大切に育てることへの投資、税金投入はたくさんの効果を生むと思います。子どもを健やかに育てることも、母親の就労、社会参加を推し進めることでも、また雇用を増やすことでも、本当に社会の発展のために大いに生かされる。今、現段階でお金がかかるというのは、本当に短期的な見方であって、将来を見据えた場合にとても効果を上げると思います。保育園が足りないということにおいては、足りてくると地域の子育てに大いに保育園が拠点となって活用されるのです。地域の方がどんどん保育園に入ってきて、保育の子育て拠点になっていくと言った意味では、保育園は本当に子育てを支える大事な大事な施設になるといった意味では、この請願が求めております園庭も必要です、公園も必要です、認可保育園の大幅増設、ぜひ応援をしていきたいと思います。\n採択を主張いたします。"},{"i":237,"speaker":"大倉委員","text":"不採択でお願いします。\n理由としては、今現在、お話をいろいろ伺った中においても、品川区ではさまざまな総合的な視点から施策を展開している中において、私たち、我が会派、民主党・無所属クラブでも、待機児童をできるだけ減らしてゼロを目指していくという中で、この認可保育園に限定して施策展開していくというよりも、総合的な施策で対応していくことのほうが、ゼロを目指していく中において効果的と考えますので、不採択としていただきたいと思います。"},{"i":238,"speaker":"高橋（し）委員","text":"不採択でお願いします。\nもうずっと言われているところですが、認可保育園を含め、さまざまな施策を総合的に展開してきていますので、それがきめ細かなことにつながっている部分があります。ただ、保育需要の正確な把握、そしてその後の動向や、それからさらに、今回の３００人の大規模ではないですけれども、スピード感というのでしょうか、それをもって総合的に進めていっていただきたいというところで、こちらの題にあるような形での限定という形ではなくて、総合的に進めていっている点で、不採択。"},{"i":239,"speaker":"塚本委員長","text":"それでは、平成２７年請願第１８号、子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願について、採決をいたします。\n本件は、挙手により採決いたします。\n本件を採択することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":240,"speaker":"塚本委員長","text":"賛成少数につき、平成２７年請願第１８号は、不採択と決定いたしました。\n以上で、請願・陳情審査を終了いたします。\n公園課長はご退席いただいて結構でございます。ありがとうございました。\n────────────────────────────────────────────\n３ 報告事項\n(1) 専決処分の報告について（報告第１５号）\n(2) 専決処分の報告について（報告第１６号）\n(3) 専決処分の報告について（報告第１７号）\n(4) 専決処分の報告について（報告第１８号）"},{"i":241,"speaker":"塚本委員長","text":"次に、予定表３、報告事項を行います。\n(1)専決処分の報告について（報告第１５号）から(4)専決処分の報告について（報告第１８号）の４件を一括して議題に供します。\n本件につきまして、理事者より一括して説明願います。"},{"i":242,"speaker":"廣田子ども家庭支援課長","text":"私からは、一括で専決処分についてご報告申し上げます。お手元に資料をＡ４、１枚ご用意してございます。報告第１５号から第１８号までまとめてご説明いたします。\n品川区の奨学金につきましては、区奨学金の貸付条例に基づいて、奨学金借受者および連帯保証人に対しまして返還を求めております。しかしながら、返済が滞っている者に対しましては、記書き以下のとおり督促を行ってまいりましたが、返還に応じない者が生じたため、地方自治法第１８０条第１項の規定により、専決処分を行いました。東京簡易裁判所に対し支払いを求める訴えの提起を専決処分により行っております。こちらが報告第１５号でございます。\nまた、このうち３件につきましては、前述の規定によりまして専決処分を行い、和解をいたしましたので、報告第１６号から第１８号にてご報告申し上げます。\n専決処分に至るまでの経過についてご説明申し上げます。\nまず、返還に応じない方に対しまして、区による督促を本人および連帯保証人に対して文書により行っております。平成２６年６月３０日現在、滞納件数は３１７件ございまして、滞納金額は４,０８２万円余でございました。\n次に、訪問督促を行っておりまして、平成１４年度からシルバー人材センターに委託をしており、品川区および近隣在住者に対する訪問督促を実施しております。訪問戸数につきましては、年間約１,８００戸行っております。\n上記の１、２の督促にもかかわらず返還に応じない者に対しまして、平成２０年度より、弁護士に債権回収の業務を委任することを始めておりまして、今回も委任しております。平成２６年度の委任件数につきましては７４件、滞納金額につきましては１,０８７万円余でございます。平成２６年８月１日に弁護士名により督促を行っております。\n弁護士による督促を行いましても、ここまで督促等対処しましても連絡等が全くない者に対しまして、訴えの提起を行っております。訴えにつきましては、平成２７年３月６日から４月２２日までに順次行っているものでございます。訴えの件数につきましては１３件で、訴額は６９２万１,０００円となってございます。詳細につきましては、資料の裏面にリストを挙げさせていただいております。\nこのうち、裏面の４番から６番につきましては和解が成立しておりまして、個別の状況に応じまして、支払能力に応じてということで、１万円から１万５,０００円ずつ、二、三年で返還するという形で和解が成立しております。\n裏面の表につきましては、１３件で、被告については２６名ということで提示をさせていただいております。"},{"i":243,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等ございましたら、ご発言願います。"},{"i":244,"speaker":"飯沼委員","text":"Ａ４のところの２の訪問督促のところですけれども、シルバー人材センターに委託ということと、訪問督促と書いてあるのですけれども、どういう中身で委託をして、実際にどんな中身で、なかなかデリケートな中身なので、どういうふうな督促をしているのか教えてください。"},{"i":245,"speaker":"廣田子ども家庭支援課長","text":"仕様といいますか、２人専従で、かつてこういう仕事をしたことがある方ということで、平成１４年から同じ方だったかと思いますけれども、督促を区から出しましてお返事がない方で、区内に住んでいる方に訪問をして事情を聞いていただくという形をしておりまして、訪問に行った段階でお支払いをしますという形で連絡をいただいている方は、集金と言ったらあれですけれども、振り込みに行ったりするのが大変であったりとかする方につきましては、顔を見て集金をするという形でお願いをしています。総価契約なので、成果払いではないです。総価でお願いしています。"},{"i":246,"speaker":"飯沼委員","text":"和解のところを見ると、具体的には１万円とか、１万５,０００円とか、払えるところで分納しているということですけれども、この辺は、早くたどり着けば、もっと気が楽というか、結構支払いできていないいろいろな事情はあるかとは思うのですけれども、期間が長ければ長いほどやっぱり負担になってしまったり、金額が膨らんだりというところにおいては、早く解決に向かうような手立ても必要であると思うのですが、この点、分納の相談とか、そういう中身にまで早くいけるような状況はあるのでしょうか。なかなかそこまで話し込めていないのかどうか。周知なども含めて教えてください。"},{"i":247,"speaker":"廣田子ども家庭支援課長","text":"早い段階では区による督促をした場合に、払うのは、現在、こういう病気をしているであるとか、こういう状態ですというご相談をいただいていれば、区の段階で分納するような形で支払いの形を変更したりしております。訪問督促につきましても、書類は来ていたけれどもというところで、シルバー人材センターのスタッフがいるところで、払いますということも来ていますが、弁護士による督促で、弁護士に７４件委任しているのですけれども、訴えの提起に至ったのが１３件ということは、弁護士名で督促を出すと連絡はいただけるのですけれども、連絡がいただけないことには、区からの督促もそうなのですが、連絡をいただけないと、支払いが難しいのであればこうしましょうというお話し合いもできないというところがいろいろございまして、弁護士による督促をしても、なおかつということは、訴えの提起をすることでご連絡いただけて和解に至っている方につきましては、そこでお話し合いが設けられまして、今回、和解に関しましては、口頭弁論の日にちに行く前にお話し合いができておりますので、そこで収入と支出、今、どのぐらい生活にかかっているかという金額をお聞きしまして、生活ができなくなっては困るので、無理のない範囲内でというところで、弁護士側から意見をいただきまして、区のほうでそこを確認をして、合意をして、こちらでという和解になっておりますので、もっと早い段階で連絡をとりたいのは区側のほうはもちろんなのですけれども、なかなか払えないからなのか、あとは借受人が保護者であったり、今は本人に貸し付けているのですが、かつては保護者に貸しておりましたので、保護者から支払いが滞ったことを本人が知らなかったであったりとかということで、文書を出して連絡をつけるということで、和解で支払っていただくのか、午前中もありましたけれども、払えないのか、払わないのかというところも含めましてできるということで、弁護士を入れたことでコンタクトのとれる件数は増えたというふうに認識しています。"},{"i":248,"speaker":"飯沼委員","text":"弁護士を入れたことで早く解決が、それも１つの解決であろうと思います。ご苦労はいろいろあるかと思いますが、なるべく早い段階できちんと相談に乗れて、早く解決できるとよいと思っております。よろしくお願いいたします。"},{"i":249,"speaker":"高橋（し）委員","text":"勉強不足なので教えていただきたいのですが、こうした債権は時効がどれぐらいで回収できなくなるのか。あるいは、時効をとめるにはどうするのか。それで訴えているのかなとは思ったりするのですが、この債権、奨学金を返していない方が、例えば住民税を滞納しているとか、国保の滞納をしているとか、そういうことを、逆もそうなのですけれども、住民税のほうもそうなのですけれども、そういうものを把握されたりはするのでしょうか。あるいは、できないのでしょうか。その辺がわからないので。そういうことが何かトータルでその方がどれだけの状況だということを把握することにつながらないというか、債権回収の優先順位というか、そういうふうにつながっていくと思うのですが、その辺はどうなのでしょうか。教えてください。"},{"i":250,"speaker":"廣田子ども家庭支援課長","text":"奨学金の貸付につきましては、私債権になりますので、民法の取り扱いになるので時効は１０年になります。督促をするところで１回、最初の督促でとか、区の私債権の管理の条例とほぼそのとおりにやってございます。\n直接強制権は持っておりませんので、こちらで強制的にお調べするということはできない状況なので、ご本人に確認をして、自己破産をしていたりとかということですと、あちらの弁護士であったりとか、公式な書類をというところで確認をするというところで、あくまでも私債権になりますので、強制力はないものでございます。"},{"i":251,"speaker":"高橋（し）委員","text":"ありがとうございます。"},{"i":252,"speaker":"石田（ち）委員","text":"どういう形で和解などが進んだのかを伺いたいと思うのですけれども、例えば、報告第１７号ですと、こういう形で進みましたということは書いてあるのですけれども、この方の実態、分納不履行になっていたということなので、話し合いになったりとか、あとは生活実態だったりとかを、どう把握して進めていったのかということをお聞きしたいのですけれども。"},{"i":253,"speaker":"廣田子ども家庭支援課長","text":"ご本人から弁護士のほうに連絡をいただきまして、弁護士から聞き取りを行っております。まず最初に、この債権について間違いないですかという確認から始まりまして、どうして払えない状況に至ったのかというところを聞いております。細かい資料を持ってきていないのですけれども、払えない状況にあったということは、病気であったりとか、そういう状況はいただいているのですけれども、現在、こういう仕事をしていて収入が幾らで、今、電気代が幾らでとか、そういうところまで全部聞きまして、生保以上の生活を残して払える金額というところで合意を、ご本人からの申し出と、それで無理がないかということを確認をさせていただいて決めております。\nこの３件につきましては、ご本人から幾らぐらいとかに関しましては、１回月幾らぐらいだったら払えますという申し入れをいただいているのですけれども、それで本当に無理がないかどうかをこちらでも収入と支出を確認しまして、大丈夫でしょうというところで和解を成立させております。"},{"i":254,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、以上で報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":255,"speaker":"塚本委員長","text":"次に、予定表４、その他を行います。\nまず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目について、所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いいたします。\nなお、本会議での質問の繰り返しにならないようにお願いいたします。\nまた、明日、この委員会で理事者からご答弁をいただき、申し出た委員以外の方にも議論に加わっていただくという形で進めていきたいと思います。\nそれでは、所管質問がございましたら、ご発言願います。"},{"i":256,"speaker":"石田（ち）委員","text":"安藤たい作議員の教科書採択のところの質問で、総合教育会議の場で教育委員長がなぜ教科書採択についての意見を区長に聞いたのかというところで、答弁がなかったと思うので、そこを改めてお聞きしたいです。\nそれともう１つ、飯沼議員のところの保育園増設、待機児ゼロへさらなる増設をのところで、待機児ゼロは区の政策目標ですという答弁があったのですけれども、政策目標というのは具体的に何なのかを伺いたいのと、あと、１,０００人を超える子どもの、先ほどの請願のところでも人数を出されましたけれども、不承諾の１,０１５人の年齢別、そして親の就労状況も聞いたのに、そこへの答弁がなかったので、そこをお聞きしたいと思います。"},{"i":257,"speaker":"塚本委員長","text":"それでは、教科書採択は、安藤議員の質問の繰り返しではなくて、どういうふうに聞きたいですか。"},{"i":258,"speaker":"石田（ち）委員","text":"なぜ聞いたのかというところ。"},{"i":259,"speaker":"塚本委員長","text":"一般質問と繰り返しになりますね。ご答弁が同じということになって、あまりここで改めて取り上げるにはちょっと不適切。\nこれは繰り返しになってしまうので、ちょっと。\nでは、待機児童については、数字が……。"},{"i":260,"speaker":"石田（ち）委員","text":"ええ、出ていなかった。"},{"i":261,"speaker":"塚本委員長","text":"出ていなかったのでということですか。"},{"i":262,"speaker":"石田（ち）委員","text":"そうです。"},{"i":263,"speaker":"塚本委員長","text":"では、それについてはよろしいでしょうか。今、待機児童の数字につきまして、明日の委員会でまた理事者の答弁ということでいただきたいと思いますので、よろしくお願いしたいと思います。"},{"i":264,"speaker":"飯沼委員","text":"今の前段のところの安藤区議のところの質問なんですけれども、明確なご答弁がなかったのです。"},{"i":265,"speaker":"塚本委員長","text":"再質問の中でもなかったですか。"},{"i":266,"speaker":"飯沼委員","text":"なかったです。質問に対してのご答弁がなかったのですね。教育委員長はなぜ……。"},{"i":267,"speaker":"塚本委員長","text":"だから、答弁がなかったとしても質問自体が同じですと、やっぱりちょっとこれは、ここでは繰り返しの答弁は……。"},{"i":268,"speaker":"飯沼委員","text":"この質問に対しての答弁という意味です。"},{"i":269,"speaker":"塚本委員長","text":"だから、質問自体が繰り返しだと、答弁がなかったということでは、ちょっとなかなか。"},{"i":270,"speaker":"飯沼委員","text":"ごめんなさい、ここの質問のところの答弁という言い方をしているのですが、今、保育のところも、私は１,０００人を超える子どもの年齢の人数と保護者の就労状況というお尋ねをしたのです。ところが、答弁は、委員会で聞いた２１５人の待機児童の返事しかなかったのです。私は１,０００人を超える子ども、だから、そちらが待機児と勝手にとったわけですが、私は間違わないように１,０００人を超える子どもたちの年齢の別と親の状況と、委員会で出なかった数字を事前に本会議で質問を事前に知らせて中身を教えてほしいという質問をしたにもかかわらず、委員会と同じ、だから２１５人ではないのです。はっきり言って、きちんと答えていないと申し上げたいので、きちんと答えていただきたい。"},{"i":271,"speaker":"塚本委員長","text":"待機児童についてはわかりました。これは数字のことなので。\n教科書採択については、質問自体が全く同じだと、同じ答えになってしまうので。"},{"i":272,"speaker":"飯沼委員","text":"だから、答弁がされていないというところで、教えていただきたいのです。"},{"i":273,"speaker":"塚本委員長","text":"されていないという認識はおそらく私としてもないので、それはちょっと取り上げられないです。"},{"i":274,"speaker":"飯沼委員","text":"そうですか。本当に理由をお伺いしたのだけれども、答弁は話されたけれども、的が全然合っていなかったのです。"},{"i":275,"speaker":"塚本委員長","text":"そこは認識の違いがあるかもしれませんけれども、所管質問でまた取り上げるということには当たらないと思いますので、ご了承のほうをお願いしたいと思います。"},{"i":276,"speaker":"金子子ども未来部長","text":"待機児童のほうなのですけれども、約１,０００人ぐらい、待機の状況といいますか、就職の状況、こちらのデータは持っていないので、２１５人のほうのデータについては把握しておりますのでお答えしたという経過です。"},{"i":277,"speaker":"塚本委員長","text":"そうすると、明日聞いてもデータがないということかもしれません。\nいずれにしても、すみません、もう明日ということで、これは回答もいただきますから。"},{"i":278,"speaker":"飯沼委員","text":"ということは、ちゃんと答えなくてもいいということになるではないですか。"},{"i":279,"speaker":"塚本委員長","text":"それはでも……。"},{"i":280,"speaker":"飯沼委員","text":"一般質問で質問したにもかかわらず。"},{"i":281,"speaker":"塚本委員長","text":"ご答弁ということで明日いただくわけですから、それでご了承いただきたいと思います。\nほかにないようですので、その他を終了いたします。\n以上で、本日の予定は全て終了いたしました。明日も午前１０時からの開会でございます。\nなお、明日の委員会で本年度の行政視察につきまして、日程や調査事項等についてのご意見をいただきたいと思いますので、よろしくお願いいたします。\nそれでは、これをもちまして、文教委員会を閉会いたします。\n○午後 ２時４８分閉会"}]});
